import React, { useEffect, useMemo, useState } from 'react';
import AvatarShowcase from '../components/AvatarShowcase';
import Footer from '../components/Footer';
import EvaaloReceptionChat from '../evaalo-only-chat/EvaaloReceptionChat';
import { useLanguage } from '../contexts/LanguageContext';

/** Landing content for Demo nav (`/demo`). Voice → WebSocket reception (`/reception`). Video avatar → `/demo/live`. */
export default function DemoPage() {
    const { currentLang } = useLanguage();
    const [chatOpen, setChatOpen] = useState(false);

    const voiceReceptionPath = useMemo(() => {
        const sessionLang = currentLang === 'en' ? 'en' : 'ar';
        return `/reception?language=${sessionLang}`;
    }, [currentLang]);

    useEffect(() => {
        window.scrollTo(0, 0);
    }, []);

    return (
        <>
            <main className="demo-marketing-page">
                <AvatarShowcase />
                <AvatarShowcase
                    sectionId="avatar-showcase-audio"
                    svgIdPrefix="audio-"
                    ctaIcon="audio"
                    copyVariant="voice"
                    tryDemoTo={voiceReceptionPath}
                />
                <AvatarShowcase
                    sectionId="avatar-showcase-3"
                    svgIdPrefix="showcase3-"
                    ctaIcon="text"
                    copyVariant="chat"
                    onTryDemo={() => setChatOpen(true)}
                />
            </main>
            <EvaaloReceptionChat open={chatOpen} onClose={() => setChatOpen(false)} />
            <Footer />
        </>
    );
}
