import React, { useCallback, useEffect, useState } from 'react';
import { useLanguage } from '../contexts/LanguageContext';
import { accountSectionLabelStyle, ACCOUNT_TEXT_MUTED } from '../utils/accountTypography';
import { fillI18nTemplate } from '../utils/i18nTemplate.js';

const STORAGE_KEY = 'evaalo_account_integrations';

const CONNECT_URLS = {
    linkedin: import.meta.env.VITE_LINKEDIN_CONNECT_URL || '',
    whatsapp: import.meta.env.VITE_WHATSAPP_CONNECT_URL || '',
};

function readStoredConnections() {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (!raw) return { linkedin: false, whatsapp: false };
        const parsed = JSON.parse(raw);
        return {
            linkedin: Boolean(parsed?.linkedin),
            whatsapp: Boolean(parsed?.whatsapp),
        };
    } catch {
        return { linkedin: false, whatsapp: false };
    }
}

function writeStoredConnections(next) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
}

