import React from 'react';
import LegalPageShell from '../components/LegalPageShell';
import { useLanguage } from '../contexts/LanguageContext';
import { getLegalDocs } from '../i18n/legalPages';
import LegalBullets from '../components/LegalBullets';

export default function DataSecurityPage() {
    const { t, currentLang } = useLanguage();
    const { security: s } = getLegalDocs(currentLang);
    const isRtl = currentLang === 'ar' || currentLang === 'ku';

    const body = (
        <>
            <div className="legal-meta-pill" aria-label={s.updated}>
                <svg
                    width="14"
                    height="14"
                    viewBox="0 0 24 24"
                    fill="none"
                    aria-hidden
                >
                    <rect
                        x="3"
                        y="5"
                        width="18"
                        height="16"
                        rx="2"
                        stroke="currentColor"
                        strokeWidth="1.6"
                    />
                    <path
                        d="M3 9h18M8 3v4M16 3v4"
                        stroke="currentColor"
                        strokeWidth="1.6"
                        strokeLinecap="round"
                    />
                </svg>
                <span>{s.updated}</span>
            </div>

            <h2>{s.s1.title}</h2>
            <p className="legal-lead">{s.s1.lead}</p>

            <h2>{s.s2.title}</h2>
            <p>{s.s2.intro}</p>
            <LegalBullets items={s.s2.bullets} />

            <h2>{s.s3.title}</h2>
            <LegalBullets items={s.s3.bullets} />

            <h2>{s.s4.title}</h2>
            <LegalBullets items={s.s4.bullets} />

            <h2>{s.s5.title}</h2>
            <p>{s.s5.intro}</p>
            <LegalBullets items={s.s5.bullets} />
            <p>{s.s5.foot}</p>

            <h2>{s.s6.title}</h2>
            <p>{s.s6.intro}</p>
            <LegalBullets items={s.s6.bullets} />

            <h2>{s.s7.title}</h2>
            <LegalBullets items={s.s7.bullets} />

            <h2>{s.s8.title}</h2>
            <p>{s.s8.intro}</p>
            <LegalBullets items={s.s8.bullets} />

            <h2>{s.s9.title}</h2>
            <p>{s.s9.p}</p>

            <h2>{s.contact.title}</h2>
            <div className="legal-contact-card">
                <p className="legal-contact-card__intro">{s.contact.intro}</p>
                <a
                    className="legal-contact-card__link"
                    href="mailto:team@evaalo.com"
                >
                    <span className="legal-contact-card__icon" aria-hidden>
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                            <rect
                                x="3"
                                y="5"
                                width="18"
                                height="14"
                                rx="2"
                                stroke="currentColor"
                                strokeWidth="1.6"
                            />
                            <path
                                d="M3 7l9 6 9-6"
                                stroke="currentColor"
                                strokeWidth="1.6"
                                strokeLinejoin="round"
                            />
                        </svg>
                    </span>
                    <span>team@evaalo.com</span>
                </a>
            </div>
        </>
    );

    return (
        <LegalPageShell title={t('dataSecurity')} variant="features">
            {isRtl ? (
                <div className="legal-page-rtl" dir="rtl" lang={currentLang}>
                    {body}
                </div>
            ) : (
                body
            )}
        </LegalPageShell>
    );
}
