/**
 * AccountBillingCancel — Stripe cancel_url landing page (Phase 2b).
 * Stripe redirects here when the user closes Checkout before paying.
 * No subscription was created — we just give the user a clear back-link.
 */

import React from 'react';
import { Link } from 'react-router-dom';
import { useLanguage } from '../contexts/LanguageContext';

const cardStyle = {
    maxWidth: 520,
    margin: '64px auto',
    padding: '40px 36px',
    borderRadius: 16,
    background: 'rgba(15, 23, 42, 0.85)',
    color: '#f1f5f9',
    boxShadow: '0 24px 60px rgba(15, 23, 42, 0.45)',
    border: '1px solid rgba(255, 255, 255, 0.08)',
};

const ctaPrimary = {
    display: 'inline-block',
    padding: '10px 20px',
    background: '#fff',
    color: '#0f172a',
    borderRadius: 10,
    fontWeight: 600,
    textDecoration: 'none',
};

export default function AccountBillingCancel() {
    const { t } = useLanguage();
    return (
        <div style={cardStyle}>
            <h1 style={{ margin: '0 0 12px', fontSize: 26, fontWeight: 700 }}>
                {t('billing_cancel_title')}
            </h1>
            <p style={{ margin: '0 0 24px', fontSize: 15, color: '#cbd5e1', lineHeight: 1.6 }}>
                {t('billing_cancel_subtitle')}
            </p>
            <Link to="/account/billing" style={ctaPrimary}>
                {t('billing_cancel_cta_back')}
            </Link>
        </div>
    );
}
