import React, { useEffect, useState } from 'react';
import {
    API_BASE,
    PdfCvLink,
    candidateAvatarImageProps,
    candidatePhotoUrl,
    stage1FilesFromCandidate,
} from '../utils/candidateAssets';
import { absoluteAppUrl } from '../config/apiBase.js';
import '../design-styles.css';
import { useLanguage } from '../contexts/LanguageContext';
import { fillI18nTemplate } from '../utils/i18nTemplate.js';
import { canonicalStageRecommendation } from '../utils/stageRecommendation.js';

const WrittenInterview = () => {
    const { t, currentLang } = useLanguage();
    const [candidates, setCandidates] = useState([]);
    const [stage1Pending, setStage1Pending] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState('all'); // all, hire, consider, reject
    const [expandedRows, setExpandedRows] = useState(new Set());

    useEffect(() => {
        fetchCandidates();
    }, []);

    useEffect(() => {
        const previous = document.title;
        document.title = `${t('writtenInterviewPageTitle')} · ${t('companyName')}`;
        return () => {
            document.title = previous;
        };
    }, [t, currentLang]);

    const fetchCandidates = async () => {
        try {
            setLoading(true);
            const response = await fetch(`${API_BASE}/api/candidates`);
            const result = await response.json();
            
            console.log('📥 Fetched candidates:', result);
            
            if (result.success && result.data) {
                const all = result.data;
                // Stage 1 يشمل فقط المرشحين الذين دخلوا عبر مسار Screening الكامل.
                // مرشحو Call/Video المباشرون (entryStage === 'audio' | 'video') مستبعدون
                // ⇒ يظهرون في Stage 2 / Stage 3 على الترتيب.
                const isScreeningCandidate = (c) =>
                    !c.entryStage || c.entryStage === 'screening';
                // مسار Start Process: نفس منطق ما قبل إضافة entryStage — وجود كائن التقييم truthy
                // (قد يكون {} افتراضياً من Mongoose) يضع المرشح في الجدول الرئيسي، وليس في كتلة «بانتظار».
                // الفصل الوحيد عن ذلك هو استبعاد entryStage الصوتي/الفيديو من Stage 1 بالكامل.
                const candidatesWithEvaluation = all.filter(
                    (c) => isScreeningCandidate(c) && c.writtenInterviewEvaluation
                );
                const pendingStage1 = all.filter(
                    (c) =>
                        isScreeningCandidate(c) &&
                        !c.writtenInterviewEvaluation &&
                        Array.isArray(c.files) &&
                        c.files.length > 0
                );
                
                console.log('📊 Candidates with Written Interview Evaluation:', candidatesWithEvaluation.length);
                console.log('📋 Stage 1 pending (CV/photo, no evaluation yet):', pendingStage1.length);
                
                setCandidates(candidatesWithEvaluation);
                setStage1Pending(pendingStage1);
            } else {
                console.warn('⚠️ No candidates data received');
            }
        } catch (error) {
            console.error('❌ Error fetching candidates:', error);
        } finally {
            setLoading(false);
        }
    };

    const translateRecLabel = (canonical) => {
        switch (canonical) {
            case 'Hire':
                return t('stageEval_recHire');
            case 'Consider':
                return t('stageEval_recConsider');
            case 'Reject':
                return t('stageEval_recReject');
            case 'N/A':
                return t('stageEval_recNa');
            default:
                return canonical;
        }
    };

    const recommendationMatchesFilter = (rawRec, filterVal) => {
        if (filterVal === 'all') return true;
        const n = String(rawRec ?? '').trim().toLowerCase();
        return n === filterVal;
    };

    const getRecommendationColor = (label) => {
        switch (label) {
            case 'Hire':
                return { bg: 'rgba(16, 185, 129, 0.2)', border: 'rgba(16, 185, 129, 0.4)', text: '#10B981' };
            case 'Consider':
                return { bg: 'rgba(245, 158, 11, 0.2)', border: 'rgba(245, 158, 11, 0.4)', text: '#F59E0B' };
            case 'Reject':
                return { bg: 'rgba(239, 68, 68, 0.2)', border: 'rgba(239, 68, 68, 0.4)', text: '#EF4444' };
            default:
                return { bg: 'rgba(148, 163, 184, 0.2)', border: 'rgba(148, 163, 184, 0.4)', text: '#94A3B8' };
        }
    };

    /** إصلاح عرض مثل 42.00000000000001٪ */
    const formatWrittenPercentDisplay = (value) => {
        const n = Number(value);
        if (!Number.isFinite(n)) return '0';
        const rounded = Math.round(n * 100) / 100;
        return rounded.toLocaleString('en-US', { maximumFractionDigits: 2, minimumFractionDigits: 0 });
    };

    const getScoreColor = (score) => {
        const n = Number(score);
        const s = Number.isFinite(n) ? Math.round(n * 100) / 100 : 0;
        if (s >= 80) return { bg: 'rgba(16, 185, 129, 0.2)', text: '#10B981' };
        if (s >= 60) return { bg: 'rgba(245, 158, 11, 0.2)', text: '#F59E0B' };
        return { bg: 'rgba(239, 68, 68, 0.2)', text: '#EF4444' };
    };

    /** Stage 1: المشاركة = رابط المقابلة الصوتية التالية */
    const handleShare = async (candidate) => {
        const candidateId = candidate._id || candidate.id;
        const camp = candidate.campaignId;
        const q = new URLSearchParams({ candidateId: String(candidateId) });
        if (camp) q.set('campaignId', String(camp));
        const interviewLink = absoluteAppUrl(`/interview?${q.toString()}`);

        const candidateData = {
            name:
                ((candidate.full_name || candidate.fullName) || '').trim()
                || candidate.email?.split('@')[0]
                || t('stageEval_unknownCandidate'),
            position:
                candidate.position_applied_for || candidate.positionAppliedFor || t('stageEval_notApplicable'),
            score: formatWrittenPercentDisplay(candidate.writtenInterviewEvaluation?.overall_score),
            recommendation: translateRecLabel(
                canonicalStageRecommendation(candidate.writtenInterviewEvaluation?.recommendation)
            ),
            summary: candidate.writtenInterviewEvaluation?.summary || t('stageEval_noSummary'),
            email: candidate.email || t('stageEval_notApplicable'),
            phone: candidate.phone || t('stageEval_notApplicable'),
        };

        const shareText = fillI18nTemplate(t('writtenInterview_shareBody'), {
            name: candidateData.name,
            position: candidateData.position,
            link: interviewLink,
            score: candidateData.score,
            recommendation: candidateData.recommendation,
            email: candidateData.email,
            phone: candidateData.phone,
            summary: candidateData.summary,
        });

        // Try Web Share API first (mobile/desktop) — إرسال رابط المقابلة الصوتية
        if (navigator.share) {
            try {
                await navigator.share({
                    title: fillI18nTemplate(t('writtenInterview_shareNavigatorTitle'), {
                        name: candidateData.name,
                    }),
                    text: fillI18nTemplate(t('writtenInterview_shareNavigatorText'), {
                        name: candidateData.name,
                        position: candidateData.position,
                        link: interviewLink,
                    }),
                    url: interviewLink
                });
                return;
            } catch (err) {
                if (err.name !== 'AbortError') {
                    console.error('Error sharing:', err);
                }
            }
        }

        // Fallback: Copy to clipboard
        try {
            await navigator.clipboard.writeText(shareText);
            alert(t('writtenInterview_shareCopyOk'));
        } catch (err) {
            console.error('Failed to copy:', err);
            prompt(`${t('writtenInterview_shareCopyPrompt')} `, shareText);
        }
    };

    const filteredCandidates = candidates.filter((c) =>
        recommendationMatchesFilter(c.writtenInterviewEvaluation?.recommendation, filter)
    );

    return (
        <>
            <style>{`
                @keyframes slideDown {
                    from {
                        opacity: 0;
                        max-height: 0;
                        transform: translateY(-10px);
                    }
                    to {
                        opacity: 1;
                        max-height: 1000px;
                        transform: translateY(0);
                    }
                }
            `}</style>
        <div style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #0F172A 0%, #1E293B 100%)' }}>
            <div
                className="design-container"
                style={{
                    paddingTop: '64px',
                    paddingBottom: '40px',
                    maxWidth: '1400px',
                    margin: '0 auto',
                    background: 'transparent',
                }}
            >
                <div className="design-header" style={{ marginBottom: '40px' }}>
                    <div className="header-content">
                        <h1 className="design-title" style={{ marginBottom: 0 }}>
                            {t('writtenInterviewPageTitle')}
                        </h1>
                        <p className="design-subtitle" style={{ marginTop: '10px', color: '#94a3b8', fontSize: '15px' }}>
                            {t('writtenInterviewSubtitle')}
                        </p>
                    </div>
                    <div className="header-actions" style={{ flexWrap: 'wrap', gap: '10px' }}>
                        <button type="button" className="btn btn-secondary" onClick={fetchCandidates}>
                            <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                <path d="M16 10C16 13.3137 13.3137 16 10 16C6.68629 16 4 13.3137 4 10C4 6.68629 6.68629 4 10 4C11.82 4 13.45 4.81 14.55 6.08" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                                <path d="M16 4V8H12" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                            </svg>
                            <span className="btn-text">{t('stageEval_refresh')}</span>
                        </button>
                        {['all', 'Hire', 'Consider', 'Reject'].map((filterOption) => {
                            const isActive = filter === filterOption.toLowerCase();
                            return (
                                <button
                                    key={filterOption}
                                    type="button"
                                    className="btn btn-secondary"
                                    onClick={() => setFilter(filterOption.toLowerCase())}
                                    style={{
                                        background: isActive ? 'rgba(34, 211, 238, 0.2)' : 'rgba(15, 23, 42, 0.8)',
                                        borderColor: isActive ? 'rgba(34, 211, 238, 0.6)' : 'rgba(34, 211, 238, 0.3)',
                                        color: isActive ? '#22d3ee' : 'rgba(255, 255, 255, 0.95)',
                                    }}
                                >
                                    {filterOption === 'all' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <path d="M2.5 5H17.5M5 10H15M7.5 15H12.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                        </svg>
                                    )}
                                    {filterOption === 'Hire' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <path d="M10 2.5L12.5 7.5L17.5 8.75L14.5 12.5L15.5 17.5L10 15L4.5 17.5L5.5 12.5L2.5 8.75L7.5 7.5L10 2.5Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                        </svg>
                                    )}
                                    {filterOption === 'Consider' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <circle cx="10" cy="10" r="7.5" stroke="currentColor" strokeWidth="2"/>
                                            <path d="M10 6V10L13 13" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                        </svg>
                                    )}
                                    {filterOption === 'Reject' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <circle cx="10" cy="10" r="7.5" stroke="currentColor" strokeWidth="2"/>
                                            <path d="M7.5 7.5L12.5 12.5M12.5 7.5L7.5 12.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                        </svg>
                                    )}
                                    <span className="btn-text">
                                        {filterOption === 'all'
                                            ? t('stageEval_all')
                                            : filterOption === 'Hire'
                                              ? t('stageEval_recHire')
                                              : filterOption === 'Consider'
                                                ? t('stageEval_recConsider')
                                                : t('stageEval_recReject')}
                                    </span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                {!loading && stage1Pending.length > 0 && (
                    <div style={{
                        marginBottom: '28px',
                        padding: '0',
                        borderRadius: '12px',
                        border: '1px solid rgba(245, 158, 11, 0.35)',
                        overflow: 'hidden',
                        background: 'rgba(15, 23, 42, 0.5)'
                    }}>
                        <div style={{ padding: '16px 20px', borderBottom: '1px solid rgba(245, 158, 11, 0.25)', color: '#FBBF24', fontWeight: 600 }}>
                            {fillI18nTemplate(t('writtenInterviewPendingBanner'), { n: stage1Pending.length })}
                        </div>
                        <div style={{ overflowX: 'auto' }}>
                            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                <thead>
                                    <tr style={{ background: 'rgba(30, 41, 59, 0.9)', color: '#CBD5E1', fontSize: '13px', textAlign: 'left' }}>
                                        <th style={{ padding: '12px 16px' }}>{t('stageEval_colCandidate')}</th>
                                        <th style={{ padding: '12px 16px', textAlign: 'center' }}>{t('stageEval_colPhoto')}</th>
                                        <th style={{ padding: '12px 16px', textAlign: 'center' }}>{t('stageEval_colCv')}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {stage1Pending.map((row) => {
                                        const { cv } = stage1FilesFromCandidate(row);
                                        const pendingPhotoUrl = candidatePhotoUrl(row);
                                        const nm = ((row.full_name || row.fullName) || '').trim() || row.email;
                                        return (
                                            <tr key={row._id || row.id} style={{ borderTop: '1px solid rgba(148, 163, 184, 0.12)', color: '#E2E8F0' }}>
                                                <td style={{ padding: '12px 16px' }}>{nm}</td>
                                                <td style={{ padding: '12px 16px', textAlign: 'center', verticalAlign: 'middle' }}>
                                                    {pendingPhotoUrl ? (
                                                        <div
                                                            className="candidate-avatar-ring"
                                                            style={{
                                                                width: '62px',
                                                                height: '62px',
                                                                borderRadius: '8px',
                                                                overflow: 'hidden',
                                                                margin: '0 auto',
                                                                border: '2px solid rgba(34, 211, 238, 0.35)',
                                                            }}
                                                        >
                                                            <img
                                                                alt=""
                                                                className="candidate-avatar-photo"
                                                                decoding="async"
                                                                draggable={false}
                                                                {...candidateAvatarImageProps(pendingPhotoUrl, 62)}
                                                                style={{
                                                                    width: '100%',
                                                                    height: '100%',
                                                                    objectFit: 'cover',
                                                                }}
                                                            />
                                                        </div>
                                                    ) : (
                                                        <span style={{ color: '#64748B', display: 'inline-block' }}>—</span>
                                                    )}
                                                </td>
                                                <td style={{ padding: '12px 16px', textAlign: 'center', verticalAlign: 'middle' }}>
                                                    {cv ? (
                                                        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', width: '100%' }}>
                                                            <PdfCvLink
                                                                href={`${API_BASE}/uploads/${encodeURIComponent(cv.filename)}`}
                                                                fileName={cv.originalName}
                                                                size={46}
                                                            />
                                                        </div>
                                                    ) : (
                                                        <span style={{ color: '#64748B', display: 'inline-block' }}>—</span>
                                                    )}
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* Table — التقييمات الكتابية المكتملة */}
                {loading ? (
                    <div style={{ textAlign: 'center', padding: '60px', color: '#94A3B8' }}>
                        {t('stageEval_loading')}
                    </div>
                ) : (
                    <div style={{
                        background: 'rgba(15, 23, 42, 0.5)',
                        borderRadius: '12px',
                        border: '1px solid rgba(34, 211, 238, 0.2)',
                        overflow: 'hidden',
                        boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)'
                    }}>
                        <div style={{ overflowX: 'auto' }}>
                            <table style={{ 
                                width: '100%', 
                                borderCollapse: 'separate',
                                borderSpacing: 0,
                                border: '1px solid rgba(34, 211, 238, 0.2)',
                                borderRadius: '8px',
                                overflow: 'hidden'
                            }}>
                                <thead>
                                    <tr style={{ 
                                        background: 'linear-gradient(180deg, rgba(30, 41, 59, 0.95) 0%, rgba(15, 23, 42, 0.95) 100%)',
                                        borderBottom: '2px solid rgba(34, 211, 238, 0.5)'
                                    }}>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'left', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px', 
                                            width: '40px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}></th>
                                        <th style={{ 
                                            padding: '16px 12px', 
                                            textAlign: 'left', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            minWidth: '200px',
                                            maxWidth: '300px',
                                            width: '22%',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colCandidate')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'left', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            minWidth: '360px',
                                            width: '52%',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('writtenInterviewColFitForRole')}</th>
                                        <th style={{ 
                                            padding: '16px 8px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '13px',
                                            width: '80px',
                                            maxWidth: '88px',
                                            minWidth: '76px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colCv')}</th>
                                        <th style={{ 
                                            padding: '16px 8px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '13px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                            whiteSpace: 'nowrap',
                                            width: '1%',
                                            maxWidth: '118px',
                                            minWidth: '100px'
                                        }}>{t('stageEval_colRecommendation')}</th>
                                        <th style={{ 
                                            padding: '10px 8px', 
                                            textAlign: 'center', 
                                            verticalAlign: 'middle',
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '12px', 
                                            width: '64px',
                                            maxWidth: '68px',
                                            minWidth: '60px'
                                        }}>{t('stageEval_colShare')}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredCandidates.map((candidate, index) => {
                                        const evaluation = candidate.writtenInterviewEvaluation;
                                        const scoreColors = getScoreColor(evaluation?.overall_score ?? 0);
                                        const recCanon = canonicalStageRecommendation(evaluation?.recommendation);
                                        const recColors = getRecommendationColor(recCanon);
                                        const candidateId = candidate._id || candidate.id;
                                        const isExpanded = expandedRows.has(candidateId);
                                        const { cv } = stage1FilesFromCandidate(candidate);
                                        const photoUrl = candidatePhotoUrl(candidate);
                                        const cvUrl = cv ? `${API_BASE}/uploads/${encodeURIComponent(cv.filename)}` : null;
                                        
                                        const toggleRow = (e) => {
                                            // Don't expand if clicking on share button
                                            if (e.target.tagName === 'BUTTON' || e.target.closest('button')) {
                                                return;
                                            }
                                            setExpandedRows(prev => {
                                                const newSet = new Set(prev);
                                                if (newSet.has(candidateId)) {
                                                    newSet.delete(candidateId);
                                                } else {
                                                    newSet.add(candidateId);
                                                }
                                                return newSet;
                                            });
                                        };
                                        
                                        return (
                                            <React.Fragment key={candidateId}>
                                            <tr 
                                                style={{
                                                    borderTop: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderBottom: index < filteredCandidates.length - 1 ? '1px solid rgba(34, 211, 238, 0.3)' : '1px solid rgba(34, 211, 238, 0.3)',
                                                    transition: 'all 0.2s ease',
                                                    cursor: 'pointer',
                                                    background: 'transparent'
                                                }}
                                                onClick={toggleRow}
                                                onMouseEnter={(e) => {
                                                    e.currentTarget.style.background = 'rgba(34, 211, 238, 0.05)';
                                                    e.currentTarget.style.borderTop = '1px solid rgba(34, 211, 238, 0.5)';
                                                    e.currentTarget.style.borderBottom = '1px solid rgba(34, 211, 238, 0.5)';
                                                }}
                                                onMouseLeave={(e) => {
                                                    e.currentTarget.style.background = 'transparent';
                                                    e.currentTarget.style.borderTop = '1px solid rgba(34, 211, 238, 0.3)';
                                                    e.currentTarget.style.borderBottom = index < filteredCandidates.length - 1 ? '1px solid rgba(34, 211, 238, 0.3)' : '1px solid rgba(34, 211, 238, 0.3)';
                                                }}
                                            >
                                                {/* Expand/Collapse Icon */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center', 
                                                    width: '40px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <svg 
                                                        width="20" 
                                                        height="20" 
                                                        viewBox="0 0 20 20" 
                                                        fill="none" 
                                                        xmlns="http://www.w3.org/2000/svg"
                                                        style={{
                                                            transform: isExpanded ? 'rotate(90deg)' : 'rotate(0deg)',
                                                            transition: 'transform 0.3s ease',
                                                            color: '#22d3ee'
                                                        }}
                                                    >
                                                        <path d="M7.5 5L12.5 10L7.5 15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                    </svg>
                                                </td>
                                                {/* Candidate Name */}
                                                <td style={{ 
                                                    padding: '12px 10px', 
                                                    minWidth: '200px',
                                                    maxWidth: '300px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)',
                                                    verticalAlign: 'middle'
                                                }}>
                                                    <div style={{ display: 'flex', alignItems: 'flex-start', gap: '10px' }}>
                                                        {/* Profile Photo */}
                                                        <div
                                                            className="candidate-avatar-ring"
                                                            style={{
                                                            width: '54px',
                                                            height: '54px',
                                                            borderRadius: '50%',
                                                            overflow: 'hidden',
                                                            flexShrink: 0,
                                                            border: '2px solid rgba(34, 211, 238, 0.35)',
                                                            background: 'linear-gradient(135deg, #06B6D4, #3B82F6)',
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            boxShadow: '0 2px 8px rgba(6, 182, 212, 0.2)'
                                                        }}
                                                        >
                                                            {photoUrl ? (
                                                                <img 
                                                                    alt={((candidate.full_name || candidate.fullName) || '').trim() || t('stageEval_profilePhotoAlt')} 
                                                                    className="candidate-avatar-photo"
                                                                    decoding="async"
                                                                    draggable={false}
                                                                    {...candidateAvatarImageProps(photoUrl, 54)}
                                                                    style={{ 
                                                                        width: '100%', 
                                                                        height: '100%', 
                                                                        objectFit: 'cover' 
                                                                    }}
                                                                    onError={(e) => {
                                                                        e.target.style.display = 'none';
                                                                        const fall = e.target.nextElementSibling;
                                                                        if (fall) fall.style.display = 'flex';
                                                                    }}
                                                                />
                                                            ) : null}
                                                            <div style={{ 
                                                                display: photoUrl ? 'none' : 'flex',
                                                                alignItems: 'center', 
                                                                justifyContent: 'center',
                                                                width: '100%',
                                                                height: '100%',
                                                                fontSize: '21px',
                                                                fontWeight: 600,
                                                                color: '#fff'
                                                            }}>
                                                                {((candidate.full_name || candidate.fullName)?.[0] || candidate.email?.[0] || '?').toUpperCase()}
                                                            </div>
                                                        </div>
                                                        <div style={{ flex: 1, minWidth: 0 }}>
                                                            <div style={{ 
                                                                color: '#F1F5F9', 
                                                                fontWeight: 600, 
                                                                marginBottom: '4px',
                                                                whiteSpace: 'normal',
                                                                wordWrap: 'break-word',
                                                                lineHeight: '1.35',
                                                                fontSize: '13px'
                                                            }}>
                                                            {((candidate.full_name || candidate.fullName) || '').trim()
                                                                ? (candidate.full_name || candidate.fullName).trim()
                                                                : candidate.email?.split('@')[0] || t('stageEval_unknownCandidate')
                                                            }
                                                        </div>
                                                        <div style={{ 
                                                            color: '#94A3B8', 
                                                            fontSize: '12px',
                                                            whiteSpace: 'normal',
                                                            wordWrap: 'break-word',
                                                            lineHeight: '1.4',
                                                            marginBottom: '4px'
                                                        }}>
                                                            {candidate.position_applied_for || candidate.positionAppliedFor || t('stageEval_notApplicable')}
                                                        </div>
                                                        {candidate.createdAt && (
                                                            <div style={{ 
                                                                color: '#64748B', 
                                                                fontSize: '11px',
                                                                whiteSpace: 'normal',
                                                                wordWrap: 'break-word',
                                                                lineHeight: '1.3',
                                                                marginTop: '4px',
                                                                display: 'flex',
                                                                alignItems: 'center',
                                                                gap: '4px'
                                                            }}>
                                                                <svg width="12" height="12" viewBox="0 0 12 12" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity: 0.7 }}>
                                                                    <circle cx="6" cy="6" r="5" stroke="currentColor" strokeWidth="1"/>
                                                                    <path d="M6 3V6L8 8" stroke="currentColor" strokeWidth="1" strokeLinecap="round"/>
                                                                </svg>
                                                                {new Date(candidate.createdAt).toLocaleString('en-US', {
                                                                    year: 'numeric',
                                                                    month: 'short',
                                                                    day: 'numeric',
                                                                    hour: '2-digit',
                                                                    minute: '2-digit'
                                                                })}
                                                            </div>
                                                        )}
                                                        </div>
                                                    </div>
                                                </td>
                                                {/* Fit for Role — أعرض عمود */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    color: '#CBD5E1', 
                                                    fontSize: '15px',
                                                    lineHeight: 1.55,
                                                    verticalAlign: 'top',
                                                    minWidth: '280px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    {evaluation?.fit_for_role || t('stageEval_notApplicable')}
                                                </td>
                                                <td style={{ 
                                                    padding: '12px 8px', 
                                                    verticalAlign: 'middle',
                                                    textAlign: 'center',
                                                    width: '80px',
                                                    maxWidth: '88px',
                                                    minWidth: '76px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}
                                                    onClick={(e) => e.stopPropagation()}
                                                >
                                                    {cvUrl ? (
                                                        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', width: '100%', minHeight: '48px' }}>
                                                            <PdfCvLink
                                                                href={cvUrl}
                                                                fileName={cv?.originalName}
                                                                size={46}
                                                            />
                                                        </div>
                                                    ) : (
                                                        <span style={{ color: '#64748B', fontSize: '12px', display: 'block', textAlign: 'center' }}>—</span>
                                                    )}
                                                </td>

                                                {/* الدرجة + التوصية في حقل واحد */}
                                                <td style={{ 
                                                    padding: '10px 6px', 
                                                    textAlign: 'center',
                                                    verticalAlign: 'middle',
                                                    maxWidth: '118px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{
                                                        display: 'flex',
                                                        flexDirection: 'column',
                                                        alignItems: 'center',
                                                        justifyContent: 'center',
                                                        gap: '6px',
                                                        width: '100%'
                                                    }}>
                                                        <div style={{
                                                            display: 'inline-block',
                                                            padding: '5px 10px',
                                                            borderRadius: '6px',
                                                            background: scoreColors.bg,
                                                            color: scoreColors.text,
                                                            fontWeight: 700,
                                                            fontSize: '14px',
                                                            lineHeight: 1.15
                                                        }}>
                                                            {formatWrittenPercentDisplay(evaluation?.overall_score)}%
                                                        </div>
                                                    <div style={{
                                                        display: 'inline-block',
                                                        padding: '4px 8px',
                                                        borderRadius: '5px',
                                                        background: recColors.bg,
                                                        border: `1px solid ${recColors.border}`,
                                                        color: recColors.text,
                                                        fontWeight: 600,
                                                            fontSize: '11px',
                                                            lineHeight: 1.15,
                                                            letterSpacing: '0.02em',
                                                    }}>
                                                        {translateRecLabel(recCanon)}
                                                        </div>
                                                    </div>
                                                </td>

                                                {/* Share Button */}
                                                <td style={{ 
                                                    padding: '10px 8px', 
                                                    textAlign: 'center',
                                                    verticalAlign: 'middle',
                                                    width: '64px',
                                                    maxWidth: '68px',
                                                    minWidth: '60px',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', width: '100%', minHeight: '52px' }}>
                                                    <button
                                                        onClick={() => handleShare(candidate)}
                                                        title={t('writtenInterviewShareTitle')}
                                                        style={{
                                                            width: '50px',
                                                            height: '50px',
                                                            borderRadius: '50%',
                                                            border: 'none',
                                                            background: 'linear-gradient(135deg, #10B981 0%, #059669 100%)',
                                                            backdropFilter: 'blur(10px)',
                                                            color: '#fff',
                                                            cursor: 'pointer',
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            fontSize: '18px',
                                                            margin: '0 auto',
                                                            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                                                            boxShadow: '0 4px 12px rgba(16, 185, 129, 0.3), 0 0 0 1px rgba(34, 211, 238, 0.4)',
                                                            position: 'relative',
                                                            overflow: 'hidden'
                                                        }}
                                                        onMouseEnter={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1.1) rotate(360deg)';
                                                            e.currentTarget.style.background = 'linear-gradient(135deg, #059669 0%, #047857 100%)';
                                                            e.currentTarget.style.boxShadow = '0 8px 24px rgba(16, 185, 129, 0.5), 0 0 0 2px rgba(34, 211, 238, 0.6)';
                                                        }}
                                                        onMouseLeave={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1) rotate(0deg)';
                                                            e.currentTarget.style.background = 'linear-gradient(135deg, #10B981 0%, #059669 100%)';
                                                            e.currentTarget.style.boxShadow = '0 4px 12px rgba(16, 185, 129, 0.3), 0 0 0 1px rgba(34, 211, 238, 0.4)';
                                                        }}
                                                        onMouseDown={(e) => {
                                                            e.currentTarget.style.transform = 'scale(0.95)';
                                                        }}
                                                        onMouseUp={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1.1) rotate(360deg)';
                                                        }}
                                                    >
                                                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                                            <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                            <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                        </svg>
                                                    </button>
                                                    </div>
                                                </td>
                                            </tr>
                                            
                                            {/* Expanded Details Row */}
                                            {isExpanded && (
                                                <tr style={{
                                                    background: 'rgba(15, 23, 42, 0.6)',
                                                    borderBottom: index < filteredCandidates.length - 1 ? '1px solid rgba(34, 211, 238, 0.2)' : 'none',
                                                    borderTop: '1px solid rgba(34, 211, 238, 0.2)'
                                                }}>
                                                    <td colSpan={6} style={{ padding: '0' }}>
                                                        <div style={{
                                                            padding: '24px',
                                                            animation: 'slideDown 0.3s ease-out'
                                                        }}>
                                                            <div style={{
                                                                display: 'grid',
                                                                gridTemplateColumns: 'repeat(2, 1fr)',
                                                                gap: '20px',
                                                                marginBottom: '20px'
                                                            }}>
                                                                {/* Strengths */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        {t('stageEval_strengths')}
                                                                    </h4>
                                                                    {evaluation?.strengths && evaluation.strengths.length > 0 ? (
                                                                        <ul style={{ margin: 0, paddingLeft: '20px', color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8' }}>
                                                                            {evaluation.strengths.map((strength, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{strength}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : (
                                                                        <span style={{ color: '#94A3B8', fontSize: '13px' }}>{t('stageEval_none')}</span>
                                                                    )}
                                                                </div>

                                                                {/* Weaknesses */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        {t('stageEval_weaknesses')}
                                                                    </h4>
                                                                    {evaluation?.weaknesses && evaluation.weaknesses.length > 0 ? (
                                                                        <ul style={{ margin: 0, paddingLeft: '20px', color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8' }}>
                                                                            {evaluation.weaknesses.map((weakness, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{weakness}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : (
                                                                        <span style={{ color: '#94A3B8', fontSize: '13px' }}>{t('stageEval_none')}</span>
                                                                    )}
                                                                </div>

                                                                {/* Summary */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        {t('stageEval_summary')}
                                                                    </h4>
                                                                    <p style={{ color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8', margin: 0 }}>
                                                                        {evaluation?.summary || t('stageEval_noSummary')}
                                                                    </p>
                                                                </div>

                                                                {/* Final HR Evaluation */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        {t('stageEval_finalHrEval')}
                                                                    </h4>
                                                                    {evaluation?.final_hr_evaluation || evaluation?.finalHrEvaluation ? (
                                                                        <p style={{ color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8', margin: 0 }}>
                                                                            {evaluation.final_hr_evaluation || evaluation.finalHrEvaluation}
                                                                        </p>
                                                                    ) : evaluation?.red_flags && evaluation.red_flags.length > 0 ? (
                                                                        <ul style={{ margin: 0, paddingLeft: '20px', color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8' }}>
                                                                            {evaluation.red_flags.map((flag, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{flag}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : (
                                                                        <span style={{ color: '#94A3B8', fontSize: '13px' }}>{t('stageEval_none')}</span>
                                                                    )}
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </td>
                                                </tr>
                                            )}
                                            </React.Fragment>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* Stats */}
                {!loading && candidates.length > 0 && (
                    <div style={{
                        marginTop: '30px',
                        display: 'grid',
                        gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
                        gap: '20px'
                    }}>
                        <div style={{
                            background: 'rgba(15, 23, 42, 0.5)',
                            padding: '20px',
                            borderRadius: '12px',
                            border: '1px solid rgba(148, 163, 184, 0.1)'
                        }}>
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_totalEvaluations')}</div>
                            <div style={{ color: '#F1F5F9', fontSize: '28px', fontWeight: 700 }}>{candidates.length}</div>
                        </div>
                        <div style={{
                            background: 'rgba(15, 23, 42, 0.5)',
                            padding: '20px',
                            borderRadius: '12px',
                            border: '1px solid rgba(148, 163, 184, 0.1)'
                        }}>
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_recHire')}</div>
                            <div style={{ color: '#10B981', fontSize: '28px', fontWeight: 700 }}>
                                {candidates.filter(c => c.writtenInterviewEvaluation?.recommendation === 'Hire').length}
                            </div>
                        </div>
                        <div style={{
                            background: 'rgba(15, 23, 42, 0.5)',
                            padding: '20px',
                            borderRadius: '12px',
                            border: '1px solid rgba(148, 163, 184, 0.1)'
                        }}>
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_recConsider')}</div>
                            <div style={{ color: '#F59E0B', fontSize: '28px', fontWeight: 700 }}>
                                {candidates.filter(c => c.writtenInterviewEvaluation?.recommendation === 'Consider').length}
                            </div>
                        </div>
                        <div style={{
                            background: 'rgba(15, 23, 42, 0.5)',
                            padding: '20px',
                            borderRadius: '12px',
                            border: '1px solid rgba(148, 163, 184, 0.1)'
                        }}>
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_recReject')}</div>
                            <div style={{ color: '#EF4444', fontSize: '28px', fontWeight: 700 }}>
                                {candidates.filter(c => c.writtenInterviewEvaluation?.recommendation === 'Reject').length}
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
        </>
    );
};

export default WrittenInterview;

