import React, { useEffect, useMemo, useState } from 'react';
import { createPortal } from 'react-dom';
import { useLanguage } from '../contexts/LanguageContext';
import { useBilling } from '../contexts/BillingContext';
import { CREDIT_BUCKETS } from '../config/billingPlans';
import {
    listPlans,
    getPriceDisplay,
    formatCreditCap,
    isPopularPlan,
    hasCustomCredits,
} from '../utils/billingDisplay';
import {
    groupFeaturesForDisplay,
    FEATURE_GROUP_ORDER,
} from '../utils/billingFeatureGroups';
import { apiClient } from '../services/apiClient';

const SHELL_BG = 'linear-gradient(180deg, rgba(30, 41, 59, 0.65) 0%, rgba(15, 23, 42, 0.72) 100%)';
const SHELL_BORDER = '2px solid rgba(255, 255, 255, 0.12)';
const SHELL_SHADOW = '0 12px 40px rgba(0, 0, 0, 0.4)';
const MUTED = '#94a3b8';
const BORDER = 'rgba(255, 255, 255, 0.1)';
const TITLE_GRADIENT = {
    background: 'linear-gradient(135deg, #60A5FA, #3B82F6)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    backgroundClip: 'text',
};

function IconCheck(props) {
    return (
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden {...props}>
            <path d="M20 6L9 17l-5-5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
    );
}

function IconInfo(props) {
    return (
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden {...props}>
            <circle cx="12" cy="12" r="10" />
            <path d="M12 16v-4M12 8h.01" strokeLinecap="round" />
        </svg>
    );
}

/**
 * Render the price label for a plan based on the billing cycle.
 * Returns a React node so we can split numeric value, suffix, and annotation.
 *
 * @param {string} planId
 * @param {'monthly'|'annual'} billing
 * @param {(k: string) => string} t
 */
function PriceLabel({ planId, billing, t }) {
    const info = getPriceDisplay(planId, billing);
    if (info.kind === 'custom') {
        return (
            <span dir="ltr" style={{ fontSize: 22, fontWeight: 700, color: '#fff', letterSpacing: '-0.02em' }}>
                {t('billing_price_custom')}
            </span>
        );
    }
    const suffix = t('billing_price_per_month');
    return (
        <span dir="ltr" style={{ display: 'inline-flex', alignItems: 'baseline', gap: 6 }}>
            <span style={{ fontSize: 22, fontWeight: 700, color: '#fff', letterSpacing: '-0.02em' }}>
                ${info.amount}
            </span>
            <span style={{ fontSize: 13, color: MUTED, fontWeight: 500 }}>
                {suffix}
                {info.kind === 'annual' ? ` · ${t('billing_price_billed_annually')}` : ''}
            </span>
        </span>
    );
}

/**
 * @param {object} props
 * @param {boolean} props.isOpen
 * @param {() => void} props.onClose
 * @param {string} [props.currentPlanId] — overrides BillingContext; rarely needed.
 * @param {'monthly' | 'annual'} [props.defaultBilling]
 * @param {string} [props.scrollToPlanId] — plan id to scroll into view ('starter' | 'professional' | 'enterprise')
 */
export function AdjustPlanModal({
    isOpen,
    onClose,
    currentPlanId: currentPlanIdProp,
    defaultBilling = 'monthly',
    scrollToPlanId,
}) {
    const { t, currentLang } = useLanguage();
    const billingCtx = useBilling();
    const currentPlanId = currentPlanIdProp || billingCtx.currentPlanId;
    const modalDir = currentLang === 'ar' || currentLang === 'ku' ? 'rtl' : 'ltr';

    const allPlans = useMemo(() => listPlans(), []);

    const [billing, setBilling] = useState(() => (defaultBilling === 'annual' ? 'annual' : 'monthly'));
    const [pendingPlanId, setPendingPlanId] = useState(null);
    const [checkoutError, setCheckoutError] = useState(null);

    const handleChoosePlan = async (planId) => {
        if (pendingPlanId) return;
        setCheckoutError(null);
        setPendingPlanId(planId);
        try {
            const res = await apiClient.post('/api/billing/checkout', { planId, cycle: billing });
            if (res?.url) {
                window.location.href = res.url;
                return;
            }
            throw new Error('billing_checkout_failed');
        } catch (err) {
            const message = err?.data?.code === 'CONTACT_SALES'
                ? t('billing_checkout_contact_sales')
                : err?.message
                  ? t('billing_checkout_failed') + (err.message ? ` — ${err.message}` : '')
                  : t('billing_checkout_failed');
            setCheckoutError(message);
            setPendingPlanId(null);
        }
    };

    const handleContactSales = () => {
        const email = 'sales@evaalo.ai';
        const subject = encodeURIComponent('Enterprise plan inquiry');
        window.location.href = `mailto:${email}?subject=${subject}`;
    };

    useEffect(() => {
        if (!isOpen) return;
        setBilling(defaultBilling === 'annual' ? 'annual' : 'monthly');
    }, [isOpen, defaultBilling]);

    useEffect(() => {
        if (!isOpen || !scrollToPlanId) return undefined;
        const ok = allPlans.some((p) => p.id === scrollToPlanId);
        if (!ok) return undefined;
        const run = () => {
            const el = document.querySelector(`.adjust-plan-modal [data-plan-id="${scrollToPlanId}"]`);
            el?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        };
        const id = requestAnimationFrame(() => {
            requestAnimationFrame(run);
        });
        return () => cancelAnimationFrame(id);
    }, [isOpen, scrollToPlanId, allPlans]);

    useEffect(() => {
        if (!isOpen) return undefined;
        const onKey = (e) => {
            if (e.key === 'Escape') onClose();
        };
        document.addEventListener('keydown', onKey);
        const prev = document.body.style.overflow;
        document.body.style.overflow = 'hidden';
        return () => {
            document.removeEventListener('keydown', onKey);
            document.body.style.overflow = prev;
        };
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    const gridColumnsClass = allPlans.length >= 4 ? 'adjust-plan-modal-grid' : 'adjust-plan-modal-grid adjust-plan-modal-grid-3';

    const currentPlan = allPlans.find((p) => p.id === currentPlanId);

    return createPortal(
        <>
            <div
                role="presentation"
                onClick={onClose}
                style={{
                    position: 'fixed',
                    inset: 0,
                    background: 'rgba(0, 0, 0, 0.75)',
                    backdropFilter: 'blur(8px)',
                    WebkitBackdropFilter: 'blur(8px)',
                    zIndex: 10001,
                    animation: 'fadeIn 0.25s ease',
                }}
            />
            <div
                dir={modalDir}
                role="dialog"
                aria-modal="true"
                aria-labelledby="adjust-plan-title"
                className="new-interview-modal adjust-plan-modal"
                onClick={(e) => e.stopPropagation()}
                style={{
                    position: 'fixed',
                    top: '50%',
                    left: '50%',
                    transform: 'translate(-50%, -50%)',
                    width: '94%',
                    maxWidth: 1180,
                    maxHeight: '92vh',
                    background: SHELL_BG,
                    backdropFilter: 'blur(24px)',
                    WebkitBackdropFilter: 'blur(24px)',
                    border: SHELL_BORDER,
                    borderRadius: 16,
                    boxShadow: SHELL_SHADOW,
                    zIndex: 10002,
                    padding: '24px 24px 20px',
                    overflow: 'hidden',
                    display: 'flex',
                    flexDirection: 'column',
                    animation: 'modalFadeIn 0.25s ease',
                }}
            >
                <div
                    style={{
                        display: 'flex',
                        alignItems: 'flex-start',
                        justifyContent: 'space-between',
                        gap: 12,
                        marginBottom: 8,
                    }}
                >
                    <div style={{ flex: 1 }} />
                    <div style={{ flex: 1, minWidth: 0, textAlign: 'center' }}>
                        <h2
                            id="adjust-plan-title"
                            style={{
                                margin: 0,
                                fontSize: 22,
                                fontWeight: 700,
                                letterSpacing: '-0.02em',
                                color: '#fff',
                            }}
                        >
                            {t('adjust_plan_title')}
                        </h2>
                        <p style={{ margin: '8px 0 0', fontSize: 14, color: MUTED, fontWeight: 500 }}>
                            {t('adjust_plan_currentLabel')}{' '}
                            <span dir="ltr" style={{ color: '#e2e8f0' }}>
                                {currentPlan ? t(currentPlan.displayNameKey) : ''}
                            </span>
                        </p>
                    </div>
                    <div style={{ flex: 1, display: 'flex', justifyContent: 'flex-end' }}>
                        <button
                            type="button"
                            className="ni-header-btn-close"
                            onClick={onClose}
                            aria-label={t('adjust_plan_closeAria')}
                        >
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                            </svg>
                        </button>
                    </div>
                </div>

                {/* Billing toggle */}
                <div
                    style={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        flexWrap: 'wrap',
                        gap: 14,
                        marginBottom: 22,
                        marginTop: 4,
                    }}
                >
                    <div
                        role="group"
                        aria-label={t('adjust_plan_billingAria')}
                        style={{
                            display: 'inline-flex',
                            padding: 4,
                            borderRadius: 999,
                            background: 'rgba(15, 23, 42, 0.85)',
                            border: `1px solid ${BORDER}`,
                        }}
                    >
                        {['monthly', 'annual'].map((key) => {
                            const active = billing === key;
                            return (
                                <button
                                    key={key}
                                    type="button"
                                    onClick={() => setBilling(key)}
                                    style={{
                                        padding: '8px 18px',
                                        borderRadius: 999,
                                        border: 'none',
                                        cursor: 'pointer',
                                        fontFamily: 'inherit',
                                        fontSize: 13,
                                        fontWeight: 600,
                                        color: active ? '#f8fafc' : MUTED,
                                        background: active ? 'rgba(255, 255, 255, 0.12)' : 'transparent',
                                        transition: 'background 0.2s ease, color 0.2s ease',
                                    }}
                                >
                                    {t(key === 'monthly' ? 'adjust_plan_monthly' : 'adjust_plan_annual')}
                                </button>
                            );
                        })}
                    </div>
                    <span style={{ fontSize: 13, fontWeight: 600, color: '#34d399' }}>
                        {t('adjust_plan_saveAnnualNote')}
                    </span>
                </div>

                {/* Plan cards */}
                <div
                    style={{
                        display: 'grid',
                        gridTemplateColumns: `repeat(${allPlans.length}, minmax(0, 1fr))`,
                        gap: 14,
                        overflowY: 'auto',
                        paddingBottom: 8,
                        flex: 1,
                        minHeight: 0,
                    }}
                    className={gridColumnsClass}
                >
                    {allPlans.map((plan) => {
                        const isCurrent = plan.id === currentPlanId;
                        const popular = isPopularPlan(plan.id);
                        const isCustomPrice = plan.price === 'custom';
                        const customCredits = hasCustomCredits(plan.id);
                        const groupedFeatures = groupFeaturesForDisplay(plan.features);

                        return (
                            <div
                                key={plan.id}
                                data-plan-id={plan.id}
                                style={{
                                    display: 'flex',
                                    flexDirection: 'column',
                                    minHeight: 480,
                                    padding: '18px 16px',
                                    borderRadius: 12,
                                    background: popular
                                        ? 'rgba(96, 165, 250, 0.08)'
                                        : 'rgba(255, 255, 255, 0.05)',
                                    border: popular
                                        ? '1px solid rgba(96, 165, 250, 0.45)'
                                        : `1px solid ${BORDER}`,
                                    boxShadow: popular
                                        ? '0 6px 26px rgba(59, 130, 246, 0.18)'
                                        : '0 4px 20px rgba(0, 0, 0, 0.2)',
                                    position: 'relative',
                                }}
                            >
                                {popular ? (
                                    <span
                                        style={{
                                            position: 'absolute',
                                            top: -10,
                                            insetInlineStart: 14,
                                            fontSize: 10,
                                            fontWeight: 700,
                                            textTransform: 'uppercase',
                                            letterSpacing: '0.06em',
                                            padding: '4px 10px',
                                            borderRadius: 999,
                                            background: 'linear-gradient(135deg, #60A5FA, #3B82F6)',
                                            color: '#fff',
                                        }}
                                    >
                                        {t('billing_badge_popular')}
                                    </span>
                                ) : null}

                                <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', marginBottom: 10 }}>
                                    <span dir="ltr" style={{ fontSize: 17, fontWeight: 700, ...TITLE_GRADIENT }}>
                                        {t(plan.displayNameKey)}
                                    </span>
                                    {isCurrent ? (
                                        <span
                                            style={{
                                                fontSize: 10,
                                                fontWeight: 700,
                                                textTransform: 'uppercase',
                                                letterSpacing: '0.04em',
                                                padding: '3px 8px',
                                                borderRadius: 6,
                                                background: 'rgba(255, 255, 255, 0.08)',
                                                color: MUTED,
                                                border: `1px solid ${BORDER}`,
                                            }}
                                        >
                                            {t('adjust_plan_badgeCurrent')}
                                        </span>
                                    ) : null}
                                </div>

                                <div
                                    style={{
                                        marginBottom: 10,
                                        textAlign: modalDir === 'rtl' ? 'end' : 'start',
                                    }}
                                >
                                    <PriceLabel planId={plan.id} billing={billing} t={t} />
                                </div>

                                <p style={{ margin: '0 0 14px', fontSize: 13, color: MUTED, lineHeight: 1.5, flexShrink: 0 }}>
                                    {t(plan.displayDescKey)}
                                </p>

                                {/* Credits caps */}
                                <div
                                    style={{
                                        display: 'flex',
                                        flexDirection: 'column',
                                        gap: 6,
                                        padding: '10px 12px',
                                        borderRadius: 8,
                                        background: 'rgba(15, 23, 42, 0.55)',
                                        border: `1px solid ${BORDER}`,
                                        marginBottom: 14,
                                    }}
                                >
                                    {CREDIT_BUCKETS.map((bucket) => (
                                        <div
                                            key={bucket}
                                            style={{
                                                display: 'flex',
                                                justifyContent: 'space-between',
                                                alignItems: 'center',
                                                gap: 8,
                                                fontSize: 12,
                                                color: '#cbd5e1',
                                            }}
                                        >
                                            <span>{t(`billing_credit_${bucket}_label`)}</span>
                                            <span
                                                dir="ltr"
                                                title={customCredits ? t('billing_enterprise_custom_credits_tooltip') : undefined}
                                                style={{
                                                    display: 'inline-flex',
                                                    alignItems: 'center',
                                                    gap: 4,
                                                    fontWeight: 700,
                                                    color: '#f1f5f9',
                                                }}
                                            >
                                                {formatCreditCap(plan.id, bucket)}
                                                <span style={{ color: MUTED, fontWeight: 500 }}>
                                                    {t('billing_credit_per_month_suffix')}
                                                </span>
                                                {customCredits ? (
                                                    <IconInfo
                                                        style={{ color: '#94a3b8', marginInlineStart: 2 }}
                                                        aria-label={t('billing_enterprise_custom_credits_tooltip')}
                                                    />
                                                ) : null}
                                            </span>
                                        </div>
                                    ))}
                                </div>

                                {/* Feature bullets grouped */}
                                <ul
                                    style={{
                                        listStyle: 'none',
                                        margin: 0,
                                        padding: 0,
                                        flex: 1,
                                        display: 'flex',
                                        flexDirection: 'column',
                                        gap: 8,
                                    }}
                                >
                                    {groupedFeatures.map(({ groupKey, features }) => (
                                        <li key={`${plan.id}-${groupKey}`} style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                                            {FEATURE_GROUP_ORDER.length > 1 ? (
                                                <span
                                                    style={{
                                                        fontSize: 10,
                                                        fontWeight: 700,
                                                        textTransform: 'uppercase',
                                                        letterSpacing: '0.06em',
                                                        color: '#64748b',
                                                    }}
                                                >
                                                    {t(`billing_feature_group_${groupKey}`)}
                                                </span>
                                            ) : null}
                                            {features.map((feature) => (
                                                <div
                                                    key={`${plan.id}-${feature}`}
                                                    style={{
                                                        display: 'flex',
                                                        alignItems: 'flex-start',
                                                        gap: 8,
                                                        fontSize: 13,
                                                        color: '#cbd5e1',
                                                        lineHeight: 1.45,
                                                    }}
                                                >
                                                    <IconCheck style={{ flexShrink: 0, marginTop: 2, color: '#94a3b8' }} />
                                                    <span>
                                                        {t(`billing_feature_${feature.replace(/\./g, '_')}`)}
                                                    </span>
                                                </div>
                                            ))}
                                        </li>
                                    ))}
                                </ul>

                                <div style={{ marginTop: 18, paddingTop: 4 }}>
                                    {isCurrent ? (
                                        <button
                                            type="button"
                                            disabled
                                            style={{
                                                width: '100%',
                                                padding: '10px 14px',
                                                borderRadius: 8,
                                                border: `1px solid ${BORDER}`,
                                                background: 'rgba(15, 23, 42, 0.6)',
                                                color: MUTED,
                                                fontWeight: 600,
                                                fontSize: 14,
                                                cursor: 'default',
                                                fontFamily: 'inherit',
                                            }}
                                        >
                                            {t('adjust_plan_btnCurrent')}
                                        </button>
                                    ) : isCustomPrice ? (
                                        <button
                                            type="button"
                                            onClick={handleContactSales}
                                            style={{
                                                width: '100%',
                                                padding: '10px 14px',
                                                borderRadius: 8,
                                                border: '1px solid rgba(255, 255, 255, 0.2)',
                                                background: 'rgba(15, 23, 42, 0.55)',
                                                color: '#fff',
                                                fontWeight: 600,
                                                fontSize: 14,
                                                cursor: 'pointer',
                                                fontFamily: 'inherit',
                                            }}
                                        >
                                            {t('adjust_plan_btnTeams')}
                                        </button>
                                    ) : (
                                        <button
                                            type="button"
                                            onClick={() => handleChoosePlan(plan.id)}
                                            disabled={Boolean(pendingPlanId)}
                                            style={{
                                                width: '100%',
                                                padding: '10px 14px',
                                                borderRadius: 8,
                                                border: 'none',
                                                background: '#ffffff',
                                                color: '#0d0d0d',
                                                fontWeight: 600,
                                                fontSize: 14,
                                                cursor: pendingPlanId ? 'wait' : 'pointer',
                                                opacity: pendingPlanId && pendingPlanId !== plan.id ? 0.6 : 1,
                                                fontFamily: 'inherit',
                                            }}
                                        >
                                            {pendingPlanId === plan.id
                                                ? t('billing_checkout_redirecting')
                                                : t('adjust_plan_btnChoose')}
                                        </button>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>

                {checkoutError ? (
                    <p
                        role="alert"
                        style={{
                            margin: '14px 0 0',
                            textAlign: 'center',
                            fontSize: 13,
                            color: '#f87171',
                            lineHeight: 1.5,
                        }}
                    >
                        {checkoutError}
                    </p>
                ) : null}

                <p
                    style={{
                        margin: '18px 0 0',
                        textAlign: 'center',
                        fontSize: 13,
                        color: MUTED,
                        lineHeight: 1.5,
                    }}
                >
                    {t('adjust_plan_footerPrefix')}{' '}
                    <a
                        href="#enterprise"
                        onClick={(e) => e.preventDefault()}
                        style={{
                            color: '#60a5fa',
                            fontWeight: 600,
                            textDecoration: 'none',
                            borderBottom: '1px solid rgba(96, 165, 250, 0.45)',
                        }}
                    >
                        {t('adjust_plan_footerLink')}
                    </a>
                    .
                </p>

                <style>{`
                    @media (max-width: 1024px) {
                        .adjust-plan-modal .adjust-plan-modal-grid {
                            grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
                        }
                    }
                    @media (max-width: 560px) {
                        .adjust-plan-modal .adjust-plan-modal-grid {
                            grid-template-columns: 1fr !important;
                        }
                    }
                `}</style>
            </div>
        </>,
        document.body
    );
}

export default AdjustPlanModal;
