import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useLanguage } from '../contexts/LanguageContext';
import '../design-styles.css';
import NewInterviewSidebar from '../components/NewInterviewSidebar';
import {
    candidateAvatarImageProps,
    candidatePhotoUrl,
    GenderAvatar,
    inferGenderFromName,
    shouldUseGenderAvatar,
} from '../utils/candidateAssets';
import { absoluteAppUrl, API_BASE_URL } from '../config/apiBase.js';
import { serviceIconTones } from '../utils/brandColor';
import PhoneCallOutlineIcon from '../components/PhoneCallOutlineIcon.jsx';
import { fillI18nTemplate as fillDashboardTemplate } from '../utils/i18nTemplate.js';
import { resolveDashboardInterviewStage } from '../utils/stageRecommendation.js';

const filledServiceIconSvgProps = {
    width: 28,
    height: 28,
    viewBox: '0 0 24 24',
    fill: 'none',
    xmlns: 'http://www.w3.org/2000/svg',
    style: { display: 'block' },
};

/** New Campaign + Settings + Templates: filled multi-tone؛ الباقي خطّي كالسابق */
function DashboardServiceIcon({ type, color }) {
    /** Templates — نفس أيقونة «استمارة / Form» في Hero (مستند بخطوط، outline) */
    if (type === 'template') {
        return (
            <svg
                width={28}
                height={28}
                viewBox="0 0 64 64"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
                style={{ display: 'block' }}
            >
                <rect x="12" y="8" width="40" height="48" rx="2" stroke={color} strokeWidth="3.5" fill="none" strokeLinejoin="round" />
                <line x1="20" y1="20" x2="44" y2="20" stroke={color} strokeWidth="3.5" strokeLinecap="round" />
                <line x1="20" y1="28" x2="44" y2="28" stroke={color} strokeWidth="3.5" strokeLinecap="round" />
                <line x1="20" y1="36" x2="36" y2="36" stroke={color} strokeWidth="3.5" strokeLinecap="round" />
                <line x1="20" y1="44" x2="40" y2="44" stroke={color} strokeWidth="3.5" strokeLinecap="round" />
            </svg>
        );
    }

    if (type === 'plus') {
        const { a, b } = serviceIconTones(color);
        return (
            <svg {...filledServiceIconSvgProps}>
                <rect x="9" y="4" width="6" height="16" rx="2" fill={b} />
                <rect x="4" y="9" width="16" height="6" rx="2" fill={a} />
            </svg>
        );
    }

    if (type === 'settings') {
        const { a, b, c, d } = serviceIconTones(color);
        return (
            <svg {...filledServiceIconSvgProps}>
                <rect x="3" y="5" width="18" height="3" rx="1.5" fill={c} />
                <rect x="3" y="10.5" width="18" height="3" rx="1.5" fill={b} />
                <rect x="3" y="16" width="18" height="3" rx="1.5" fill={d} />
                <circle cx="15" cy="6.5" r="2.25" fill={a} />
                <circle cx="8" cy="12" r="2.25" fill={a} />
                <circle cx="13" cy="17.5" r="2.25" fill={a} />
            </svg>
        );
    }

    const p = {
        width: 26,
        height: 26,
        viewBox: '0 0 24 24',
        fill: 'none',
        xmlns: 'http://www.w3.org/2000/svg',
    };
    const s = { stroke: color, strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' };

    switch (type) {
        /** Chart — مخطط هيكل تنظيمي (org chart) */
        case 'clipboard':
            return (
                <svg {...p}>
                    <rect x="8" y="2" width="8" height="5" rx="1.5" fill="none" {...s} />
                    <path d="M12 7v2.5M6 9.5h12M6 9.5V12M18 9.5V12" {...s} />
                    <rect x="2" y="12" width="8" height="6" rx="1.5" fill="none" {...s} />
                    <rect x="14" y="12" width="8" height="6" rx="1.5" fill="none" {...s} />
                </svg>
            );
        /** Candidates — مجموعة أشخاص */
        case 'users':
            return (
                <svg {...p}>
                    <path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2" {...s} />
                    <circle cx="9" cy="7" r="4" {...s} />
                    <path d="M23 21v-2a4 4 0 00-3-3.87M16 3.13a4 4 0 010 7.75" {...s} />
                </svg>
            );
        /** Stage 1 — مستند مكتوب (مقابلة كتابية) */
        case 'pen':
            return (
                <svg {...p}>
                    <path
                        d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8l-6-6z"
                        {...s}
                    />
                    <path d="M14 2v6h6" {...s} />
                    <path d="M8 13h8M8 17h6M8 9h4" {...s} />
                </svg>
            );
        /** Stage 2 — مكالمة (سماعة + موجات) */
        case 'mic':
            return <PhoneCallOutlineIcon color={color} size={26} strokeWidth={2} />;
        /** Stage 3 — كاميرا فيديو */
        case 'video':
            return (
                <svg {...p}>
                    <path
                        d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"
                        {...s}
                    />
                </svg>
            );
        /** Account — ملف شخصي */
        case 'user':
            return (
                <svg {...p}>
                    <circle cx="12" cy="8" r="4" {...s} />
                    <path d="M4 20v-1a6 6 0 016-6h4a6 6 0 016 6v1" {...s} />
                </svg>
            );
        /** AI HeadHunter — عدسة بحث عن مواهب */
        case 'headhunter':
            return (
                <svg {...p}>
                    <circle cx="11" cy="11" r="7" {...s} />
                    <path d="M21 21l-4.3-4.3" {...s} />
                </svg>
            );
        default:
            return (
                <svg {...p}>
                    <circle cx="12" cy="12" r="10" {...s} />
                </svg>
            );
    }
}

const DASHBOARD_UNKNOWN = 'Unknown';
const DASHBOARD_NA = 'N/A';

function dashboardDateLocale(lang) {
    if (lang === 'ar') return 'ar-IQ';
    if (lang === 'ku') return 'ckb-IQ';
    return 'en-US';
}

const DASHBOARD_SERVICE_DEFS = [
    { id: 'newCampaign', iconKey: 'plus' },
    { id: 'headhunter', iconKey: 'headhunter' },
    { id: 'templates', iconKey: 'template' },
    { id: 'stage1', iconKey: 'pen' },
    { id: 'stage2', iconKey: 'mic' },
    { id: 'stage3', iconKey: 'video' },
    { id: 'candidates', iconKey: 'users' },
    { id: 'chart', iconKey: 'clipboard' },
    { id: 'settings', iconKey: 'settings' },
    { id: 'account', iconKey: 'user' },
];

const DASHBOARD_SERVICE_THEMES = {
    newCampaign: { c1: '#3b82f6', c2: '#8b5cf6' },
    headhunter: { c1: '#22d3ee', c2: '#a855f7' },
    chart: { c1: '#06b6d4', c2: '#3b82f6' },
    candidates: { c1: '#8b5cf6', c2: '#ec4899' },
    stage1: { c1: '#22c55e', c2: '#10b981' },
    stage2: { c1: '#f59e0b', c2: '#f97316' },
    stage3: { c1: '#ec4899', c2: '#f43f5e' },
    settings: { c1: '#14b8a6', c2: '#0ea5e9' },
    account: { c1: '#0ea5e9', c2: '#6366f1' },
    templates: { c1: '#a855f7', c2: '#3b82f6' },
};

const Dashboard = () => {
    const { t, currentLang } = useLanguage();
    const navigate = useNavigate();
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [recentInterviews, setRecentInterviews] = useState([]);
    const [loadingInterviews, setLoadingInterviews] = useState(true);
    const mockRecentInterviews = [
        { id: 'mock-1', candidate: 'Ahmed Al-Mansouri', position: 'Software Engineer', status: 'pending', date: '2025-01-15' },
        { id: 'mock-2', candidate: 'Sarah Johnson', position: 'Product Manager', status: 'pending', date: '2025-01-14' },
        { id: 'mock-3', candidate: 'Mohammed Hassan', position: 'Data Analyst', status: 'pending', date: '2025-01-13' },
        { id: 'mock-4', candidate: 'Emily Chen', position: 'UX Designer', status: 'pending', date: '2025-01-12' }
    ];

    // جلب بيانات المرشحين من API
    useEffect(() => {
        const fetchRecentInterviews = async () => {
            try {
                setLoadingInterviews(true);
                const response = await fetch(`${API_BASE_URL}/api/candidates`);
                const result = await response.json();
                
                if (result.success && result.data) {
                    // تحويل البيانات إلى تنسيق Recent Interviews
                    const interviews = result.data
                        .map((candidate) => {
                            const name = ((candidate.full_name || candidate.fullName) || '').trim()
                                || candidate.candidate || candidate.email?.split('@')[0] || DASHBOARD_UNKNOWN;
                            
                            // تحديد المرحلة — نفس منطق صفحات Stage 1/2/3 (تقديم الفورم = Stage 1)
                            const stage = resolveDashboardInterviewStage(candidate);
                            
                            return {
                                id: candidate._id || candidate.id,
                                candidate: name,
                                full_name: candidate.full_name || candidate.fullName,
                                position: candidate.position_applied_for || candidate.positionAppliedFor || DASHBOARD_NA,
                                stage: stage,
                                campaignId: candidate.campaignId,
                                entryStage: candidate.entryStage,
                                date: candidate.interviewDate || candidate.createdAt || new Date().toISOString().split('T')[0],
                                originalStatus: candidate.status,
                                email: candidate.email,
                                photoUrl: candidatePhotoUrl(candidate),
                                writtenInterviewEvaluation: candidate.writtenInterviewEvaluation,
                                voiceInterviewEvaluation: candidate.voiceInterviewEvaluation,
                                videoInterviewEvaluation: candidate.videoInterviewEvaluation
                            };
                        })
                        .sort((a, b) => {
                            // ترتيب حسب التاريخ (الأحدث أولاً)
                            return new Date(b.date) - new Date(a.date);
                        }); // عرض جميع المقابلات
                    
                    setRecentInterviews(interviews.length > 0 ? interviews : mockRecentInterviews);
                } else {
                    setRecentInterviews(mockRecentInterviews);
                }
            } catch (error) {
                console.error('Error fetching recent interviews:', error);
                setRecentInterviews(mockRecentInterviews);
            } finally {
                setLoadingInterviews(false);
            }
        };

        fetchRecentInterviews();
    }, []);

    const dateLocale = useMemo(() => dashboardDateLocale(currentLang), [currentLang]);

    const services = useMemo(
        () =>
            DASHBOARD_SERVICE_DEFS.map((s) => ({
                ...s,
                title: t(`dashboardSvc_${s.id}`),
                description: t(`dashboardSvcDesc_${s.id}`),
            })),
        [t, currentLang]
    );

    // Handle sidebar option selection
    const handleSidebarOption = (optionId) => {
        console.log('Selected option:', optionId);
        switch(optionId) {
            case 'start-process':
                // Navigate to start process page or show form
                console.log('Start Process selected');
                break;
            case 'video-interview':
                // Navigate to video interview page
                console.log('Video Interview selected');
                break;
            case 'audio-interview':
                // Navigate to audio interview page
                console.log('Audio Interview selected');
                break;
            case 'application-form':
                console.log('Application form selected');
                break;
            default:
                break;
        }
    };

    /**
     * Stage 1 & 2 → voice interview (/interview). Stage 3 → video (/video-interview-call).
     */
    const handleShareInterview = async (interview) => {
        const candidateId = interview.id;
        const camp = interview.campaignId;
        const stage = interview.stage;
        const q = new URLSearchParams({ candidateId: String(candidateId) });
        if (camp) q.set('campaignId', String(camp));

        const stageNum = Number(stage);
        const useVideo = stageNum === 3;
        const interviewLink = useVideo
            ? absoluteAppUrl(`/video-interview-call?${q.toString()}`)
            : absoluteAppUrl(`/interview?${q.toString()}`);

        const candidateLabel =
            interview.candidate === DASHBOARD_UNKNOWN
                ? t('dashboardUnknownCandidate')
                : interview.candidate;
        const positionLabel =
            interview.position === DASHBOARD_NA ? t('dashboardNa') : interview.position;
        const dateStr = new Date(interview.date).toLocaleDateString(dateLocale);
        const stageBadges =
            interview.stage != null ? `${t('dashboardStage')} ${interview.stage}` : '?';

        const shareVars = {
            name: candidateLabel,
            position: positionLabel,
            date: dateStr,
            stage: stageBadges,
            email: interview.email || t('dashboardNa'),
            link: interviewLink,
            url: interviewLink,
        };

        const shareText = fillDashboardTemplate(
            useVideo ? t('dashboardShareClipboardVideo') : t('dashboardShareClipboardVoice'),
            shareVars
        );

        if (navigator.share) {
            try {
                await navigator.share({
                    title: fillDashboardTemplate(
                        useVideo
                            ? t('dashboardNavigatorShareTitleVideo')
                            : t('dashboardNavigatorShareTitleVoice'),
                        { name: candidateLabel }
                    ),
                    text: fillDashboardTemplate(
                        useVideo
                            ? t('dashboardShareNavigatorTextVideo')
                            : t('dashboardShareNavigatorTextVoice'),
                        {
                            name: candidateLabel,
                            position: positionLabel,
                            url: interviewLink,
                        }
                    ),
                    url: interviewLink
                });
                return;
            } catch (err) {
                if (err.name !== 'AbortError') {
                    console.error('Error sharing:', err);
                }
            }
        }

        try {
            await navigator.clipboard.writeText(shareText);
            alert(useVideo ? `✅ ${t('dashboardShareCopiedVideo')}` : `✅ ${t('dashboardShareCopiedVoice')}`);
        } catch (err) {
            console.error('Failed to copy:', err);
            prompt(
                useVideo ? t('dashboardSharePromptVideo') : t('dashboardSharePromptVoice'),
                shareText
            );
        }
    };

    return (
        <>
        <div
            className="dashboard-page dashboard-page--evaalo-visual dashboard-home-page"
            style={{
            minHeight: '100vh', 
                padding: '70px 20px 40px',
                color: '#ffffff',
                position: 'relative',
            }}
        >
                {/* Background — نفس عائلة ألوان قسم Features (أوراق دافئة + بنفسجي/سماوي) */}
                <div className="design-background design-background--evaalo-visual">
                    <div className="design-orb-1"></div>
                    <div className="design-orb-2"></div>
                    <div className="design-orb-3"></div>
                </div>
                {/* نسيج بصري مثل #features: نقاط + شبكة خفيفة */}
                <div className="dashboard-evaalo-visual-texture" aria-hidden="true" />
                <div className="dashboard-evaalo-visual-gridlines" aria-hidden="true" />

                <div className="container dashboard-visual-container" style={{ 
                    maxWidth: '1400px', 
                    margin: '0 auto', 
                    position: 'relative', 
                    zIndex: 1,
                    minHeight: 'calc(100vh - 250px)'
                }}>
                    {/* Main Content Grid */}
                    <div className="dashboard-grid" style={{ 
                        marginBottom: '40px'
                    }}>
                        {/* Our Services */}
                        <div className="dashboard-card dashboard-card--page-active platform-features-card">
                            <div className="dashboard-card-header">
                                <h2 className="dashboard-card-title">{t('dashboardOurServices')}</h2>
                            </div>
                            <div className="dashboard-card-body">
                                {/* Platform service cards (grid) */}
                                <div style={{
                                    display: 'grid',
                                    gridTemplateColumns: 'repeat(3, 1fr)',
                                    gap: '20px'
                                }}
                                className="platform-features-grid">
                                    {services.map((service) => {
                                        const theme =
                                            DASHBOARD_SERVICE_THEMES[service.id] || {
                                                c1: '#3b82f6',
                                                c2: '#06b6d4',
                                            };

                                        const handleClick = () => {
                                            switch (service.id) {
                                                case 'newCampaign':
                                                    setIsSidebarOpen(true);
                                                    break;
                                                case 'headhunter':
                                                    navigate('/ai-head-hunter');
                                                    break;
                                                case 'chart':
                                                    navigate('/employees');
                                                    break;
                                                case 'settings':
                                                    console.log('Settings');
                                                    break;
                                                case 'stage1':
                                                    navigate('/screening');
                                                    break;
                                                case 'stage2':
                                                    navigate('/call-evaluation');
                                                    break;
                                                case 'stage3':
                                                    navigate('/video-evaluation');
                                                    break;
                                                case 'account':
                                                    navigate('/account');
                                                    break;
                                                case 'candidates':
                                                    navigate('/candidates');
                                                    break;
                                                case 'templates':
                                                    navigate('/interview-templates');
                                                    break;
                                                default:
                                                    break;
                                            }
                                        };

                                        const isAccountCard = service.id === 'account';

                                        return (
                                            <button
                                                key={service.id}
                                                type="button"
                                                onClick={handleClick}
                                                className={`ds-service-card${isAccountCard ? ' ds-service-card--dashboard-account' : ''}`}
                                                style={{
                                                    '--ds-c1': theme.c1,
                                                    '--ds-c2': theme.c2,
                                                }}
                                            >
                                                <span className="ds-service-card__glow" aria-hidden />
                                                <span className="ds-service-card__shine" aria-hidden />
                                                <span className="ds-service-card__content">
                                                    <span className="ds-service-card__icon-wrap">
                                                        <DashboardServiceIcon type={service.iconKey} color="#ffffff" />
                                                    </span>
                                                    <span className="ds-service-card__title">
                                                        {service.title}
                                                    </span>
                                                    {service.description && (
                                                        <span className="ds-service-card__desc">
                                                            {service.description}
                                                        </span>
                                                    )}
                                                </span>
                                                <span className="ds-service-card__arrow" dir="ltr" aria-hidden>
                                                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden>
                                                        <path
                                                            d="M5 12h14M13 5l7 7-7 7"
                                                            stroke="currentColor"
                                                            strokeWidth="2"
                                                            strokeLinecap="round"
                                                            strokeLinejoin="round"
                                                        />
                                                    </svg>
                                                </span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        </div>

                        {/* Recent Interviews — زجاج مطابق لـ Account sidebar */}
                        <div className="dashboard-card dashboard-card--page-active platform-features-card recent-interviews-card">
                            <div className="dashboard-card-header">
                                <h2 className="dashboard-card-title">{t('dashboardRecentInterviews')}</h2>
                                <button
                                    type="button"
                                    aria-label={t('dashboardClearRecentAria')}
                                    className="btn btn-secondary dashboard-delete-btn"
                                    onClick={() => {
                                        setRecentInterviews([]);
                                    }}
                                >
                                    <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                        <path d="M2.5 5H4.16667H17.5M6.66667 5V3.33333C6.66667 2.89131 6.84226 2.46738 7.15482 2.15482C7.46738 1.84226 7.89131 1.66667 8.33333 1.66667H11.6667C12.1087 1.66667 12.5326 1.84226 12.8452 2.15482C13.1577 2.46738 13.3333 2.89131 13.3333 3.33333V5M15.8333 5V16.6667C15.8333 17.1087 15.6577 17.5326 15.3452 17.8452C15.0326 18.1577 14.6087 18.3333 14.1667 18.3333H5.83333C5.39131 18.3333 4.96738 18.1577 4.65482 17.8452C4.34226 17.5326 4.16667 17.1087 4.16667 16.6667V5H15.8333Z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                                        <path d="M8.33333 9.16667V14.1667" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                                        <path d="M11.6667 9.16667V14.1667" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                                    </svg>
                                </button>
                            </div>
                            <div className="dashboard-card-body recent-interviews-scroll">
                                {loadingInterviews ? (
                                    <div style={{ textAlign: 'center', padding: '40px', color: '#94A3B8' }}>
                                        {t('dashboardLoadingInterviews')}
                                    </div>
                                ) : recentInterviews.length === 0 ? (
                                    <div style={{ textAlign: 'center', padding: '40px', color: '#94A3B8' }}>
                                        {t('dashboardNoInterviews')}
                                    </div>
                                ) : (
                                    <div className="interview-list">
                                        {recentInterviews.map((interview) => {
                                            const rowName =
                                                interview.candidate === DASHBOARD_UNKNOWN
                                                    ? t('dashboardUnknownCandidate')
                                                    : interview.candidate;
                                            const rowPosition =
                                                interview.position === DASHBOARD_NA
                                                    ? t('dashboardNa')
                                                    : interview.position;
                                            const rowDate = new Date(interview.date).toLocaleDateString(
                                                dateLocale
                                            );
                                            return (
                                            <div key={interview.id} className="interview-item" style={{
                                            cursor: 'pointer'
                                        }}>
                                            <div style={{ flex: 1, display: 'flex', alignItems: 'center', gap: '12px' }}>
                                                {/* Profile Photo */}
                                                <div
                                                    className="candidate-avatar-ring"
                                                    style={{
                                                    width: '48px',
                                                    height: '48px',
                                                    borderRadius: '50%',
                                                    overflow: 'hidden',
                                                    flexShrink: 0,
                                                    border: 'none',
                                                    background: 'linear-gradient(135deg, #06B6D4, #3B82F6)',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center',
                                                    boxShadow:
                                                        '0 0 0 2px rgba(34, 211, 238, 0.35), 0 2px 8px rgba(6, 182, 212, 0.2)'
                                                }}
                                                >
                                                    {interview.photoUrl ? (
                                                        <img 
                                                            alt={rowName || t('dashboardProfileAlt')} 
                                                            className="candidate-avatar-photo"
                                                            decoding="async"
                                                            draggable={false}
                                                            {...candidateAvatarImageProps(interview.photoUrl, 48)}
                                                            style={{ 
                                                                width: '100%', 
                                                                height: '100%', 
                                                                objectFit: 'cover' 
                                                            }}
                                                            onError={(e) => {
                                                                e.target.style.display = 'none';
                                                                const fall = e.target.nextElementSibling;
                                                                if (fall) fall.style.display = 'flex';
                                                            }}
                                                        />
                                                    ) : null}
                                                    {shouldUseGenderAvatar(interview, interview.photoUrl) ? (
                                                        <GenderAvatar
                                                            gender={inferGenderFromName(interview)}
                                                            size={48}
                                                        />
                                                    ) : (
                                                        <div style={{
                                                            display: interview.photoUrl ? 'none' : 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            width: '100%',
                                                            height: '100%',
                                                            fontSize: '16px',
                                                            fontWeight: 600,
                                                            color: '#fff'
                                                        }}>
                                                            {(rowName?.[0] || interview.email?.[0] || '?').toUpperCase()}
                                                        </div>
                                                    )}
                                                </div>
                                                <div>
                                                    <div className="interview-title">{rowName}</div>
                                                    <div className="interview-meta">
                                                        {rowPosition} • {rowDate}
                                                    </div>
                                                </div>
                                            </div>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                                {interview.stage ? (
                                                    <span className="status-badge status-completed" style={{
                                                        padding: '4px 8px',
                                                        fontSize: '10px',
                                                        fontWeight: 600
                                                    }}>
                                                        {t('dashboardStage')} {interview.stage}
                                                    </span>
                                                ) : (
                                                    <span className="status-badge status-pending" style={{
                                                        padding: '4px 8px',
                                                        fontSize: '10px',
                                                        fontWeight: 600
                                                    }}>
                                                        {t('dashboardPending')}
                                                    </span>
                                                )}
                                                {interview.stage === 3 ? (
                                                    <div style={{
                                                        width: '32px',
                                                        height: '32px',
                                                        borderRadius: '50%',
                                                        border: '1px solid rgba(16, 185, 129, 0.4)',
                                                        background: 'linear-gradient(135deg, #10B981 0%, #059669 100%)',
                                                        display: 'flex',
                                                        alignItems: 'center',
                                                        justifyContent: 'center',
                                                        boxShadow: '0 2px 8px rgba(16, 185, 129, 0.3)'
                                                    }}>
                                                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                                            <path d="M20 6L9 17L4 12" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
                                                        </svg>
                                                    </div>
                                                ) : interview.stage ? (
                                                    <button
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            handleShareInterview(interview);
                                                        }}
                                                        title={t('dashboardShareInterviewLinkTitle')}
                                                        style={{
                                                            width: '32px',
                                                            height: '32px',
                                                            borderRadius: '50%',
                                                            border: '1px solid rgba(34, 211, 238, 0.4)',
                                                            background: 'linear-gradient(135deg, #10B981 0%, #059669 100%)',
                                                            backdropFilter: 'blur(10px)',
                                                            color: '#fff',
                                                            cursor: 'pointer',
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            fontSize: '14px',
                                                            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                                                            boxShadow: '0 2px 8px rgba(16, 185, 129, 0.3)',
                                                            padding: 0
                                                        }}
                                                        onMouseEnter={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1.1) rotate(360deg)';
                                                            e.currentTarget.style.background = 'linear-gradient(135deg, #059669 0%, #047857 100%)';
                                                            e.currentTarget.style.boxShadow = '0 4px 12px rgba(16, 185, 129, 0.5)';
                                                        }}
                                                        onMouseLeave={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1) rotate(0deg)';
                                                            e.currentTarget.style.background = 'linear-gradient(135deg, #10B981 0%, #059669 100%)';
                                                            e.currentTarget.style.boxShadow = '0 2px 8px rgba(16, 185, 129, 0.3)';
                                                        }}
                                                    >
                                                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                                            <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                            <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                        </svg>
                                                    </button>
                                                ) : null}
                                            </div>
                                        </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* New Campaign Sidebar */}
            <NewInterviewSidebar
                isOpen={isSidebarOpen}
                onClose={() => setIsSidebarOpen(false)}
                onSelectOption={handleSidebarOption}
            />
        </>
    );
};

export default Dashboard;