/**
 * Horizontal drag-scroll for wide `.candidates-data-table` wrappers (grab / grab-to-pan columns).
 * Skips interactive targets so clicks on checkboxes and links behave normally.
 */
export function onCandidatesTableHorizontalDragMouseDown(e) {
    if (e.target.closest('button, input, select, textarea, a, [role="link"]')) return;
    const container = e.currentTarget;
    const startX = e.pageX - container.offsetLeft;
    const initialScroll = container.scrollLeft;
    let isDown = true;
    const dragThresholdPx = 8;

    const handleMouseMove = (ev) => {
        if (!isDown) return;
        const x = ev.pageX - container.offsetLeft;
        const delta = x - startX;
        if (Math.abs(delta) < dragThresholdPx) return;
        ev.preventDefault();
        container.scrollLeft = initialScroll - delta * 2;
    };

    const handleMouseUp = () => {
        isDown = false;
        container.style.cursor = 'grab';
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
    };

    container.style.cursor = 'grabbing';
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
}
