import React, { useCallback, useEffect, useMemo, useState } from 'react';
import AccountSidebar from '../components/AccountSidebar';
import AccountPageLayout from '../components/AccountPageLayout';
import AdjustPlanModal from '../components/AdjustPlanModal';
import { useLanguage } from '../contexts/LanguageContext';
import { useBilling } from '../contexts/BillingContext';
import { getPlanById, getPriceDisplay, listPlans } from '../utils/billingDisplay';
import { CREDIT_BUCKETS } from '../config/billingPlans';
import { fillI18nTemplate } from '../utils/i18nTemplate.js';
import { accountPageH1Style, accountSectionLabelStyleCompact, ACCOUNT_TEXT_PRIMARY, ACCOUNT_TEXT_MUTED } from '../utils/accountTypography';

const BORDER = 'rgba(255, 255, 255, 0.1)';
const MUTED = ACCOUNT_TEXT_MUTED;
const PROGRESS = '#38bdf8';

const ONDEMAND_LIMIT_STORAGE_KEY = 'account-spending-ondemand-limit';

/** @returns {{ limitType: 'fixed' | 'unlimited', monthlyLimit: string }} */
function loadOndemandLimit() {
    if (typeof localStorage === 'undefined') return { limitType: 'fixed', monthlyLimit: '200' };
    try {
        const raw = localStorage.getItem(ONDEMAND_LIMIT_STORAGE_KEY);
        if (!raw) return { limitType: 'fixed', monthlyLimit: '200' };
        const p = JSON.parse(raw);
        const lt = p?.limitType;
        const ml = p?.monthlyLimit;
        if (lt === 'unlimited' && typeof ml === 'string') return { limitType: 'unlimited', monthlyLimit: ml };
        if (lt === 'fixed' && typeof ml === 'string') {
            const n = Number(ml);
            if (Number.isFinite(n) && n >= 0) return { limitType: 'fixed', monthlyLimit: String(Math.floor(n)) };
        }
    } catch {
        /* ignore */
    }
    return { limitType: 'fixed', monthlyLimit: '200' };
}

/** @param {{ limitType: string, monthlyLimit: string }} saved @param {(k: string) => string} t */
function formatSavedCap(saved, t) {
    if (saved.limitType === 'unlimited') return t('account_spending_unlimitedCap');
    const n = Math.floor(Math.max(0, Number(saved.monthlyLimit) || 0));
    return `$${n}`;
}

function IconChevronDown(props) {
    return (
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
            <path d="M6 9l6 6 6-6" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
    );
}

const AccountSpending = () => {
    const { currentLang, t } = useLanguage();
    const { currentPlanId, balances } = useBilling();
    const mainDir = currentLang === 'ar' || currentLang === 'ku' ? 'rtl' : 'ltr';

    const currentPlan = getPlanById(currentPlanId);
    const currentPriceInfo = getPriceDisplay(currentPlanId, 'monthly');
    const currentPriceLabel =
        currentPriceInfo.kind === 'custom'
            ? t('billing_price_custom')
            : `$${currentPriceInfo.amount}${t('billing_price_per_month')}`;
    const allPlans = listPlans();
    const currentIndex = allPlans.findIndex((p) => p.id === currentPlanId);
    const upgradePlan = currentIndex >= 0 && currentIndex < allPlans.length - 1 ? allPlans[currentIndex + 1] : null;
    const upgradePriceInfo = upgradePlan ? getPriceDisplay(upgradePlan.id, 'monthly') : null;
    const upgradePriceLabel = !upgradePlan
        ? ''
        : upgradePriceInfo.kind === 'custom'
            ? t('billing_price_custom')
            : `$${upgradePriceInfo.amount}${t('billing_price_per_month')}`;
    const includedInLabel = currentPlan
        ? fillI18nTemplate(t('billing_account_included_in_plan'), { plan: t(currentPlan.displayNameKey) })
        : '';
    const [limitType, setLimitType] = useState('fixed');
    const [monthlyLimit, setMonthlyLimit] = useState('200');
    const [savedOndemand, setSavedOndemand] = useState(() => ({ limitType: 'fixed', monthlyLimit: '200' }));
    const [includedExpanded, setIncludedExpanded] = useState(false);
    const [adjustPlanOpen, setAdjustPlanOpen] = useState(false);
    const [planModalDefaultBilling, setPlanModalDefaultBilling] = useState('monthly');
    const [planModalScrollTo, setPlanModalScrollTo] = useState(null);

    const closePlanModal = useCallback(() => {
        setAdjustPlanOpen(false);
        setPlanModalScrollTo(null);
    }, []);

    const openAdjustPlan = useCallback((scrollTo = null) => {
        setPlanModalDefaultBilling('monthly');
        setPlanModalScrollTo(scrollTo);
        setAdjustPlanOpen(true);
    }, []);

    useEffect(() => {
        const stored = loadOndemandLimit();
        setLimitType(stored.limitType);
        setMonthlyLimit(stored.monthlyLimit);
        setSavedOndemand(stored);
    }, []);

    const normalizedDraft = useMemo(() => {
        if (limitType !== 'fixed') return monthlyLimit;
        return String(Math.floor(Math.max(0, Number(monthlyLimit) || 0)));
    }, [limitType, monthlyLimit]);

    const invalidFixed =
        limitType === 'fixed' &&
        (Number.isNaN(Number(monthlyLimit)) || Number(monthlyLimit) < 0 || monthlyLimit === '');

    const ondemandDirty = useMemo(() => {
        if (limitType !== savedOndemand.limitType) return true;
        if (limitType === 'fixed') return normalizedDraft !== String(Math.floor(Math.max(0, Number(savedOndemand.monthlyLimit) || 0)));
        return false;
    }, [limitType, normalizedDraft, savedOndemand]);

    const handleSaveOndemand = useCallback(() => {
        if (invalidFixed) return;
        if (limitType === 'fixed') {
            const next = { limitType: 'fixed', monthlyLimit: normalizedDraft };
            try {
                localStorage.setItem(ONDEMAND_LIMIT_STORAGE_KEY, JSON.stringify(next));
            } catch {
                /* ignore quota */
            }
            setMonthlyLimit(normalizedDraft);
            setSavedOndemand(next);
            return;
        }
        const next = { limitType: 'unlimited', monthlyLimit };
        try {
            localStorage.setItem(ONDEMAND_LIMIT_STORAGE_KEY, JSON.stringify(next));
        } catch {
            /* ignore */
        }
        setSavedOndemand(next);
    }, [invalidFixed, limitType, monthlyLimit, normalizedDraft]);

    const limitTypeBtn = (id, label) => {
        const active = limitType === id;
        return (
            <button
                key={id}
                type="button"
                onClick={() => setLimitType(id)}
                className={`workflow-btn-primary account-usage-pill${active ? ' account-usage-pill--on' : ''}`}
            >
                {label}
            </button>
        );
    };

    const spendingInjectStyle = `
                @media (max-width: 960px) {
                    .account-dashboard-inner { flex-direction: column !important; }
                    .account-spending-page aside {
                        position: relative !important;
                        top: 0 !important;
                        width: 100% !important;
                    }
                    .account-spending-plan-row {
                        grid-template-columns: 1fr !important;
                    }
                }
            `;

    const ondemandCapLabel = fillI18nTemplate(t('account_spending_ondemandRatio'), {
        cap: formatSavedCap(savedOndemand, t),
    });

    const creditUsage = useMemo(() => {
        const plan = getPlanById(currentPlanId);
        const pctByBucket = {};
        let totalIncluded = 0;
        let totalUsed = 0;

        for (const bucket of CREDIT_BUCKETS) {
            const included = plan?.credits?.[bucket]?.included ?? 0;
            const remaining = Math.max(0, balances?.[bucket] ?? 0);
            const used = Math.max(0, included - remaining);
            const pct = included > 0 ? Math.round((used / included) * 100) : 0;
            pctByBucket[bucket] = Math.min(100, Math.max(0, pct));
            totalIncluded += included;
            totalUsed += used;
        }

        const overallPct =
            totalIncluded > 0 ? Math.min(100, Math.round((totalUsed / totalIncluded) * 100)) : 0;

        return { pctByBucket, overallPct };
    }, [currentPlanId, balances]);

    const breakdownToggleLabel = fillI18nTemplate(t('account_spending_breakdownToggle'), {
        voicePct: creditUsage.pctByBucket.voice ?? 0,
        videoPct: creditUsage.pctByBucket.video ?? 0,
        searchPct: creditUsage.pctByBucket.search ?? 0,
        voice: t('account_spending_voice_short'),
        video: t('account_spending_video_short'),
        search: t('account_spending_search_short'),
    });

    return (
        <AccountPageLayout pageClass="account-spending-page" injectStyle={spendingInjectStyle}>
                <AccountSidebar activeId="spending" />

                <main dir={mainDir} style={{ flex: 1, minWidth: 0 }}>
                    <h1 style={accountPageH1Style('0 0 28px')}>{t('account_spending_title')}</h1>

                    {/* Plan row */}
                    <div
                        style={{
                            display: 'grid',
                            gridTemplateColumns: 'repeat(2, 1fr)',
                            gap: 16,
                            marginBottom: 16,
                        }}
                        className="account-spending-plan-row"
                    >
                        <div className="dashboard-card" style={{ padding: '22px 24px' }}>
                            <div style={accountSectionLabelStyleCompact}>{t('account_spending_currentPlan')}</div>
                            <div style={{ fontSize: 20, fontWeight: 700, marginBottom: 8, color: ACCOUNT_TEXT_PRIMARY }}>
                                <span dir="ltr">{currentPlan ? t(currentPlan.displayNameKey) : ''}</span>{' '}
                                <span dir="ltr" style={{ color: MUTED, fontWeight: 600 }}>
                                    {currentPriceLabel}
                                </span>
                            </div>
                            <p style={{ margin: '0 0 20px', fontSize: 14, color: MUTED, lineHeight: 1.5 }}>
                                {t('account_spending_planResetHint')}
                            </p>
                            <button
                                type="button"
                                className="workflow-btn-primary account-btn-compact"
                                onClick={() => openAdjustPlan(null)}
                            >
                                {t('account_planAdjust')}
                            </button>
                        </div>
                        {upgradePlan ? (
                            <div className="dashboard-card" style={{ padding: '22px 24px' }}>
                                <div style={accountSectionLabelStyleCompact}>{t('account_spending_upgradeAvailable')}</div>
                                <div style={{ fontSize: 20, fontWeight: 700, marginBottom: 8, color: ACCOUNT_TEXT_PRIMARY }}>
                                    <span dir="ltr">{t(upgradePlan.displayNameKey)}</span>{' '}
                                    <span dir="ltr" style={{ color: MUTED, fontWeight: 600 }}>
                                        {upgradePriceLabel}
                                    </span>
                                </div>
                                <p style={{ margin: '0 0 20px', fontSize: 14, color: MUTED, lineHeight: 1.5 }}>
                                    {t('account_spending_upgradeBlurb')}
                                </p>
                                <button
                                    type="button"
                                    className="workflow-btn-primary account-btn-compact"
                                    onClick={() => openAdjustPlan(upgradePlan.id)}
                                >
                                    {t('account_spending_upgradeBtn')}
                                </button>
                            </div>
                        ) : (
                            <div className="dashboard-card" style={{ padding: '22px 24px' }} />
                        )}
                    </div>

                    {/* Included in {plan} */}
                    <div className="dashboard-card" style={{ padding: '22px 24px', marginBottom: 16 }}>
                        <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 18, color: ACCOUNT_TEXT_PRIMARY }}>
                            {includedInLabel}
                        </div>
                        <div
                            style={{
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'baseline',
                                marginBottom: 10,
                            }}
                        >
                            <span style={{ fontSize: 14, color: MUTED }}>{t('account_spending_total')}</span>
                            <span style={{ fontSize: 15, fontWeight: 700 }}>{creditUsage.overallPct}%</span>
                        </div>
                        <div
                            style={{
                                height: 10,
                                borderRadius: 5,
                                background: 'rgba(15, 23, 42, 0.75)',
                                overflow: 'hidden',
                                marginBottom: 14,
                            }}
                        >
                            <div
                                style={{
                                    width: `${creditUsage.overallPct}%`,
                                    height: '100%',
                                    borderRadius: 5,
                                    background: PROGRESS,
                                }}
                            />
                        </div>
                        <button
                            type="button"
                            onClick={() => setIncludedExpanded((v) => !v)}
                            className="btn btn-secondary btn-large account-btn-disclosure"
                        >
                            <span>{breakdownToggleLabel}</span>
                            <IconChevronDown
                                style={{
                                    transform: includedExpanded ? 'rotate(180deg)' : 'none',
                                    flexShrink: 0,
                                    transition: 'transform 0.2s ease',
                                }}
                            />
                        </button>
                        {includedExpanded ? (
                            <p style={{ margin: '12px 0 0', fontSize: 13, color: MUTED, lineHeight: 1.5 }}>
                                {t('account_spending_breakdownDetail')}
                            </p>
                        ) : null}
                    </div>

                    {/* On-Demand Usage */}
                    <div className="dashboard-card" style={{ padding: '22px 24px' }}>
                        <div
                            style={{
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'baseline',
                                flexWrap: 'wrap',
                                gap: 12,
                                marginBottom: 12,
                            }}
                        >
                            <span style={{ fontSize: 15, fontWeight: 600 }}>{t('account_spending_ondemandHeading')}</span>
                            <span dir="ltr" style={{ fontSize: 15, fontWeight: 700, color: '#fff' }}>
                                {ondemandCapLabel}
                            </span>
                        </div>
                        <p style={{ margin: '0 0 28px', fontSize: 14, color: MUTED, lineHeight: 1.55, maxWidth: 720 }}>
                            {t('account_spending_ondemandBlurb')}
                        </p>

                        <div
                            style={{
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'flex-start',
                                flexWrap: 'wrap',
                                gap: 20,
                            }}
                        >
                            <div style={{ flex: 1, minWidth: 220 }}>
                                <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 6, color: ACCOUNT_TEXT_PRIMARY }}>
                                    {t('account_spending_monthlyLimit')}
                                </div>
                                <p style={{ margin: 0, fontSize: 14, color: MUTED, lineHeight: 1.5 }}>
                                    {t('account_spending_monthlyLimitHelp')}
                                </p>
                            </div>
                            <div
                                style={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    flexWrap: 'wrap',
                                    gap: 10,
                                }}
                            >
                                <div
                                    className="account-usage-segment"
                                    role="group"
                                    aria-label={t('account_spending_selectAria')}
                                    style={{
                                        display: 'inline-flex',
                                        alignItems: 'center',
                                        padding: 3,
                                        borderRadius: 8,
                                        border: `1px solid ${BORDER}`,
                                        background: 'rgba(15, 23, 42, 0.45)',
                                        gap: 2,
                                    }}
                                >
                                    {limitTypeBtn('fixed', t('account_spending_optFixed'))}
                                    {limitTypeBtn('unlimited', t('account_spending_optUnlimited'))}
                                </div>
                                <div
                                    className={`account-spending-amount-field${
                                        limitType !== 'fixed' ? ' account-spending-amount-field--disabled' : ''
                                    }${invalidFixed ? ' account-spending-amount-field--invalid' : ''}`}
                                >
                                    <span className="account-spending-amount-prefix" aria-hidden="true">
                                        $
                                    </span>
                                    <input
                                        type="number"
                                        className="account-spending-amount-input"
                                        value={monthlyLimit}
                                        onChange={(e) => setMonthlyLimit(e.target.value)}
                                        disabled={limitType !== 'fixed'}
                                        min={0}
                                        inputMode="numeric"
                                        dir="ltr"
                                        aria-label={t('account_spending_monthlyLimit')}
                                    />
                                </div>
                                <button
                                    type="button"
                                    disabled={!ondemandDirty || invalidFixed}
                                    onClick={handleSaveOndemand}
                                    className="workflow-btn-primary account-btn-compact"
                                >
                                    {t('account_spending_save')}
                                </button>
                            </div>
                        </div>
                    </div>
                </main>

                <AdjustPlanModal
                    isOpen={adjustPlanOpen}
                    onClose={closePlanModal}
                    defaultBilling={planModalDefaultBilling}
                    scrollToPlanId={planModalScrollTo ?? undefined}
                />
        </AccountPageLayout>
    );
};

export default AccountSpending;
