import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useLanguage } from '../contexts/LanguageContext';

/** صفحة Design غير جاهزة للعامة؛ الإخفاء من الشريط فقط — المسار /design يبقى يعمل مباشرة */
const SHOW_DESIGN_IN_NAV = false;

const Navigation = () => {
    const { currentLang, changeLanguage, t } = useLanguage();
    const navRef = useRef(null);
    
    useEffect(() => {
        // Apply evaalo styling to all nav links
        const elements = navRef.current?.querySelectorAll('.nav-link');
        elements?.forEach(el => {
            // Only process if evaalo exists and is not already wrapped
            if (el.innerHTML && el.innerHTML.includes('evaalo') && !el.innerHTML.includes('evaalo-text-en')) {
                // Replace evaalo with wrapped version, avoiding already wrapped ones
                el.innerHTML = el.innerHTML.replace(/\bevaalo\b/gi, '<span class="evaalo-text-en">$&</span>');
            }
        });
    }, [t, currentLang]);

    const location = useLocation();
    /** إخفاء شريط التنقل في بوابة الدفع وصفحات المصادقة */
    const hideNavOnRoutes = ['/account/billing/portal', '/login', '/signup', '/forgot-password'];
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [desktopLangDropdownOpen, setDesktopLangDropdownOpen] = useState(false);
    const [langDropdownOpen, setLangDropdownOpen] = useState(false);
    const desktopLangRef = useRef(null);
    const langDropdownRef = useRef(null);
    const desktopLangTimeoutRef = useRef(null);
    
    const isActive = (path) => location.pathname === path;
    const isDemoNavActive = location.pathname === '/demo' || location.pathname.startsWith('/demo/');

    const languages = [
        { code: 'en', name: 'English' },
        { code: 'ar', name: 'العربية', codeText: '' },
        { code: 'ku', name: 'کوردی', codeText: '(KU)' }
    ];

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (desktopLangRef.current && !desktopLangRef.current.contains(event.target)) {
                if (desktopLangTimeoutRef.current) {
                    clearTimeout(desktopLangTimeoutRef.current);
                    desktopLangTimeoutRef.current = null;
                }
                setDesktopLangDropdownOpen(false);
            }
            if (langDropdownRef.current && !langDropdownRef.current.contains(event.target)) {
                setLangDropdownOpen(false);
            }
        };

        document.addEventListener('click', handleClickOutside);
        return () => {
            document.removeEventListener('click', handleClickOutside);
            if (desktopLangTimeoutRef.current) {
                clearTimeout(desktopLangTimeoutRef.current);
            }
        };
    }, []);

    useEffect(() => {
        // Navigation effects
    }, [location.pathname]);

    const handleLanguageChange = (lang) => {
        changeLanguage(lang);
        setDesktopLangDropdownOpen(false);
        setLangDropdownOpen(false);
    };

    if (hideNavOnRoutes.includes(location.pathname)) {
        return null;
    }

    return (
        <>
            <nav className="main-nav" ref={navRef}>
                <div className="nav-container">
                    <Link to="/" className="nav-logo-img" onClick={() => setMobileMenuOpen(false)}>
                        <img src="/images/last logo.png" alt="evaalo Logo" className="logo-image" />
                        <span className="logo-text">vaalo.Ai</span>
                    </Link>
                    
                    <div className="nav-links nav-links-desktop" id="navMenuDesktop">
                        <Link to="/" className="nav-link" onClick={() => window.scrollTo(0, 0)}>{t('home')}</Link>
                        <Link to="/demo" className={`nav-link ${isDemoNavActive ? 'active' : ''}`}>{t('navDemo')}</Link>
                        {location.pathname === '/' && (
                            <>
                                <a href="#features" className="nav-link">{t('features')}</a>
                                <a href="#features-2" className="nav-link">{t('evaaloVisualLanguage')}</a>
                                <a href="#process" className="nav-link">{t('applicationProcess')}</a>
                            </>
                        )}
                        {SHOW_DESIGN_IN_NAV && (
                            <Link to="/design" className={`nav-link ${isActive('/design') ? 'active' : ''}`}>{t('design')}</Link>
                        )}

                        <div 
                            className="nav-link nav-link-dropdown" 
                            id="navLanguageItemDesktop"
                            ref={desktopLangRef}
                            onMouseEnter={() => {
                                // إلغاء أي timeout عند دخول الماوس للزر
                                if (desktopLangTimeoutRef.current) {
                                    clearTimeout(desktopLangTimeoutRef.current);
                                    desktopLangTimeoutRef.current = null;
                                }
                                setDesktopLangDropdownOpen(true);
                            }}
                            onMouseLeave={() => {
                                // تأخير طويل (500ms) عند مغادرة الزر لإعطاء وقت للانتقال للقائمة
                                desktopLangTimeoutRef.current = setTimeout(() => {
                                    setDesktopLangDropdownOpen(false);
                                }, 500); // تأخير 500ms قبل الإغلاق
                            }}
                        >
                            <span>{t('language')}</span>
                            <svg className="dropdown-arrow" width="12" height="8" viewBox="0 0 12 8" fill="none" xmlns="http://www.w3.org/2000/svg">
                                <path d="M1 1.5L6 6.5L11 1.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                            </svg>
                            <div 
                                className={`nav-language-dropdown ${desktopLangDropdownOpen ? 'active' : ''}`}
                                id="navLanguageDropdownDesktop"
                                onMouseEnter={() => {
                                    // إلغاء أي timeout عند دخول الماوس للقائمة
                                    if (desktopLangTimeoutRef.current) {
                                        clearTimeout(desktopLangTimeoutRef.current);
                                        desktopLangTimeoutRef.current = null;
                                    }
                                    setDesktopLangDropdownOpen(true);
                                }}
                                onMouseLeave={() => {
                                    // عند مغادرة القائمة، إغلاق مباشرة (بدون timeout)
                                    setDesktopLangDropdownOpen(false);
                                }}
                            >
                                {languages.map(lang => (
                                    <button
                                        key={lang.code}
                                        className={`nav-language-option ${currentLang === lang.code ? 'active' : ''}`}
                                        role="menuitem"
                                        data-lang={lang.code}
                                        onClick={() => handleLanguageChange(lang.code)}
                                    >
                                        <span className="language-name">{lang.name}</span>
                                        {lang.codeText && <span className="language-code">{lang.codeText}</span>}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                    
                    <Link 
                        to="/dashboard" 
                        className={`nav-dashboard-link ${isActive('/dashboard') ? 'active' : ''}`}
                        onClick={() => {
                            setMobileMenuOpen(false);
                        }}
                    >
                        {t('dashboard')}
                    </Link>
                    
                    <div className="nav-menu-wrapper">
                        <button 
                            className="nav-menu-toggle" 
                            id="navMenuToggle"
                            aria-label="Navigation Menu"
                            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                        >
                            <span className="hamburger-icon">
                                <span className="hamburger-line"></span>
                                <span className="hamburger-line"></span>
                                <span className="hamburger-line"></span>
                            </span>
                        </button>
                        <div className={`nav-links nav-links-mobile ${mobileMenuOpen ? 'active' : ''}`} id="navMenu">
                            <Link to="/" className="nav-link" onClick={() => setMobileMenuOpen(false)}>{t('home')}</Link>
                            <Link to="/demo" className={`nav-link ${isDemoNavActive ? 'active' : ''}`} onClick={() => setMobileMenuOpen(false)}>{t('navDemo')}</Link>
                            {location.pathname === '/' && (
                                <>
                                    <a href="#features" className="nav-link" onClick={() => setMobileMenuOpen(false)}>{t('features')}</a>
                                    <a href="#features-2" className="nav-link" onClick={() => setMobileMenuOpen(false)}>{t('evaaloVisualLanguage')}</a>
                                    <a href="#process" className="nav-link" onClick={() => setMobileMenuOpen(false)}>{t('applicationProcess')}</a>
                                </>
                            )}
                            {SHOW_DESIGN_IN_NAV && (
                                <Link to="/design" className={`nav-link ${isActive('/design') ? 'active' : ''}`} onClick={() => setMobileMenuOpen(false)}>{t('design')}</Link>
                            )}
                        </div>
                    </div>
                </div>
            </nav>

            <div className="language-selector-wrapper">
                <button 
                    className="language-icon-button" 
                    id="languageDropdownBtn"
                    aria-haspopup="true"
                    aria-expanded={langDropdownOpen}
                    onClick={() => setLangDropdownOpen(!langDropdownOpen)}
                    ref={langDropdownRef}
                >
                    <div className="language-feature-icon">
                        <img src="/images/icon8-removebg-preview.png" alt="Language Icon" className="language-icon-image" />
                    </div>
                </button>
                <div 
                    className={`language-dropdown-menu ${langDropdownOpen ? 'active' : ''}`}
                    id="languageDropdownMenu"
                    role="menu"
                >
                    {languages.map(lang => (
                        <button
                            key={lang.code}
                            className={`language-option ${currentLang === lang.code ? 'active' : ''}`}
                            role="menuitem"
                            data-lang={lang.code}
                            onClick={() => handleLanguageChange(lang.code)}
                        >
                            <span className="language-name">{lang.name}</span>
                            {lang.codeText && <span className="language-code">{lang.codeText}</span>}
                        </button>
                    ))}
                </div>
            </div>
        </>
    );
};

export default Navigation;
