/**
 * AccountBillingSuccess — Stripe success_url landing page (Phase 2b).
 *
 * Flow on mount:
 *   1. Ask BillingContext.startFastRefresh to fast-poll /api/billing/status
 *      every 2 s for up to ~30 s, stopping early once subscriptionStatus is
 *      active or trialing.
 *   2. Render plan name + balances pulled directly from BillingContext.
 *
 * Polling lifecycle is owned entirely by BillingContext; this page only
 * declares its intent. Stripe usually delivers `checkout.session.completed`
 * within 5–30 s, well within the fast-poll budget.
 */

import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useLanguage } from '../contexts/LanguageContext';
import { useBilling } from '../contexts/BillingContext';
import { getPlanById } from '../utils/billingDisplay';

const FAST_POLL_DURATION_MS = 30_000;
const FAST_POLL_INTERVAL_MS = 2_000;

const isActivatedStatus = (status) => status === 'active' || status === 'trialing';

const cardStyle = {
    maxWidth: 520,
    margin: '64px auto',
    padding: '40px 36px',
    borderRadius: 16,
    background: 'rgba(15, 23, 42, 0.85)',
    color: '#f1f5f9',
    boxShadow: '0 24px 60px rgba(15, 23, 42, 0.45)',
    border: '1px solid rgba(255, 255, 255, 0.08)',
};

const ctaPrimary = {
    display: 'inline-block',
    padding: '10px 20px',
    background: '#fff',
    color: '#0f172a',
    borderRadius: 10,
    fontWeight: 600,
    textDecoration: 'none',
};

const ctaSecondary = {
    display: 'inline-block',
    padding: '10px 20px',
    background: 'rgba(255, 255, 255, 0.08)',
    color: '#f8fafc',
    borderRadius: 10,
    fontWeight: 500,
    textDecoration: 'none',
    border: '1px solid rgba(255, 255, 255, 0.12)',
};

export default function AccountBillingSuccess() {
    const { t } = useLanguage();
    const {
        startFastRefresh,
        stopFastRefresh,
        subscriptionStatus,
        currentPlanId,
        balances,
    } = useBilling();
    const [isActive, setIsActive] = useState(isActivatedStatus(subscriptionStatus));

    useEffect(() => {
        startFastRefresh({
            durationMs: FAST_POLL_DURATION_MS,
            intervalMs: FAST_POLL_INTERVAL_MS,
            stopWhen: (snapshot) => isActivatedStatus(snapshot?.subscriptionStatus),
        });
        return () => {
            stopFastRefresh();
        };
    }, [startFastRefresh, stopFastRefresh]);

    useEffect(() => {
        if (isActivatedStatus(subscriptionStatus)) {
            setIsActive(true);
        }
    }, [subscriptionStatus]);

    const plan = currentPlanId ? getPlanById(currentPlanId) : null;
    const planLabel = plan ? t(plan.displayNameKey) : null;

    return (
        <div style={cardStyle}>
            <h1 style={{ margin: '0 0 12px', fontSize: 26, fontWeight: 700 }}>
                {isActive ? t('billing_success_title') : t('billing_success_pending_title')}
            </h1>
            <p style={{ margin: '0 0 24px', fontSize: 15, color: '#cbd5e1', lineHeight: 1.6 }}>
                {isActive ? t('billing_success_subtitle') : t('billing_success_pending_subtitle')}
            </p>

            {isActive && planLabel ? (
                <div
                    style={{
                        padding: '14px 16px',
                        borderRadius: 12,
                        background: 'rgba(96, 165, 250, 0.12)',
                        border: '1px solid rgba(96, 165, 250, 0.35)',
                        marginBottom: 24,
                    }}
                >
                    <div style={{ fontSize: 12, color: '#93c5fd', textTransform: 'uppercase', letterSpacing: '0.06em' }}>
                        {t('account_spending_currentPlan')}
                    </div>
                    <div style={{ fontSize: 18, fontWeight: 700, marginTop: 4 }}>{planLabel}</div>
                    {balances ? (
                        <div
                            style={{
                                marginTop: 12,
                                display: 'grid',
                                gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
                                gap: 8,
                                fontSize: 13,
                            }}
                        >
                            <div>
                                <div style={{ color: '#cbd5e1' }}>{t('billing_credit_voice_label')}</div>
                                <div style={{ fontWeight: 700 }}>{balances.voice}</div>
                            </div>
                            <div>
                                <div style={{ color: '#cbd5e1' }}>{t('billing_credit_video_label')}</div>
                                <div style={{ fontWeight: 700 }}>{balances.video}</div>
                            </div>
                            <div>
                                <div style={{ color: '#cbd5e1' }}>{t('billing_credit_search_label')}</div>
                                <div style={{ fontWeight: 700 }}>{balances.search}</div>
                            </div>
                        </div>
                    ) : null}
                </div>
            ) : null}

            <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                <Link to="/dashboard" style={ctaPrimary}>
                    {t('billing_success_cta_dashboard')}
                </Link>
                <Link to="/account/billing/portal" style={ctaSecondary}>
                    {t('billing_success_cta_portal')}
                </Link>
            </div>
        </div>
    );
}
