import React, { useEffect, useState } from 'react';
import {
    candidateAvatarImageProps,
    candidatePhotoUrl,
    GenderAvatar,
    inferGenderFromName,
    shouldUseGenderAvatar,
} from '../utils/candidateAssets';
import '../design-styles.css';
import { absoluteAppUrl, API_BASE_URL } from '../config/apiBase.js';
import { useLanguage } from '../contexts/LanguageContext';
import { fillI18nTemplate } from '../utils/i18nTemplate.js';
import { canonicalStageRecommendation } from '../utils/stageRecommendation.js';

/** نص من n8n قد يكون "undefined" حرفياً — لا نعرض كائنات أو undefined */
function displayVoiceText(v, fallback = 'N/A') {
    if (v === undefined || v === null) return fallback;
    if (typeof v === 'object') return fallback;
    if (typeof v === 'string') {
        const t = v.trim();
        if (t === '' || /^undefined$/i.test(t) || /^null$/i.test(t)) return fallback;
        return t;
    }
    if (typeof v === 'number' && Number.isFinite(v)) return String(v);
    const s = String(v);
    if (/^undefined$/i.test(s.trim()) || /^null$/i.test(s.trim())) return fallback;
    return s;
}

/** strengths/weaknesses قد تصل كنص أو مصفوفة من n8n */
function normalizeVoiceBulletList(raw) {
    if (raw === undefined || raw === null) return [];
    if (Array.isArray(raw)) {
        return raw
            .map((x) => (typeof x === 'string' ? x.trim() : String(x).trim()))
            .filter((x) => x && !/^undefined$/i.test(x) && !/^null$/i.test(x));
    }
    if (typeof raw === 'string') {
        const t = raw.trim();
        if (!t || /^undefined$/i.test(t) || /^null$/i.test(t)) return [];
        return t
            .split(/\n+|(?:\s*,\s*)/)
            .map((s) => s.trim())
            .filter(Boolean);
    }
    return [];
}

/** مهارة: رقم /10 أو نص (كلمات) */
function formatVoiceSkill(v, naLabel, outOfTenTpl) {
    if (v === undefined || v === null) return naLabel;
    if (typeof v === 'number' && Number.isFinite(v)) return fillI18nTemplate(outOfTenTpl, { n: v });
    return displayVoiceText(v, naLabel);
}

const VoiceInterview = () => {
    const { t, currentLang } = useLanguage();
    const na = t('stageEval_notApplicable');
    const skillOutTen = t('stageEval_skillOutOfTen');

    const translateRecLabel = (canonical) => {
        switch (canonical) {
            case 'Hire':
                return t('stageEval_recHire');
            case 'Consider':
                return t('stageEval_recConsider');
            case 'Reject':
                return t('stageEval_recReject');
            case 'N/A':
                return t('stageEval_recNa');
            default:
                return canonical;
        }
    };

    const recommendationMatchesFilter = (rawRec, filterVal) => {
        if (filterVal === 'all') return true;
        const n = String(rawRec ?? '').trim().toLowerCase();
        return n === filterVal;
    };

    const [candidates, setCandidates] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState('all'); // all, hire, consider, reject
    const [expandedRows, setExpandedRows] = useState(new Set());

    useEffect(() => {
        fetchCandidates();
    }, []);

    useEffect(() => {
        const previous = document.title;
        document.title = `${t('voiceInterviewPageTitle')} · ${t('companyName')}`;
        return () => {
            document.title = previous;
        };
    }, [t, currentLang]);

    // Stage 2: POST /webhook/n8n/stage2 — voiceInterviewEvaluation
    // communication / problem_solving: number أو نص | strengths / weaknesses: مصفوفة أو سطر
    const fetchCandidates = async () => {
        try {
            setLoading(true);
            const response = await fetch(`${API_BASE_URL}/api/candidates`);
            const result = await response.json();
            
            console.log('📥 Fetched candidates:', result);
            
            if (result.success && result.data) {
                // Stage 2 يضمّ:
                //   1) مرشحين أتت تقييماتهم من n8n (voiceInterviewEvaluation موجود مع محتوى).
                //   2) مرشحون مباشرون من زر Call (entryStage === 'audio') حتى قبل وصول التقييم
                //      ⇒ يظهرون كحاوية فارغة جاهزة لاستقبال نتائج n8n لاحقاً.
                const hasMeaningfulEvaluation = (e) =>
                    e && (
                        e.recommendation ||
                        e.overall_score != null ||
                        e.summary ||
                        e.final_hr_evaluation
                    );
                const candidatesWithEvaluation = result.data.filter(
                    candidate => {
                        const isDirectAudio = candidate.entryStage === 'audio';
                        const hasEvaluation = hasMeaningfulEvaluation(candidate.voiceInterviewEvaluation);
                        return isDirectAudio || hasEvaluation;
                    }
                );
                
                console.log('📊 Candidates with Voice Interview Evaluation:', candidatesWithEvaluation.length);
                console.log('📋 All candidates:', result.data.length);
                
                setCandidates(candidatesWithEvaluation);
            } else {
                console.warn('⚠️ No candidates data received');
            }
        } catch (error) {
            console.error('❌ Error fetching candidates:', error);
        } finally {
            setLoading(false);
        }
    };

    const getRecommendationColor = (recommendation) => {
        switch (recommendation) {
            case 'Hire':
                return { bg: 'rgba(16, 185, 129, 0.2)', border: 'rgba(16, 185, 129, 0.4)', text: '#10B981' };
            case 'Consider':
                return { bg: 'rgba(245, 158, 11, 0.2)', border: 'rgba(245, 158, 11, 0.4)', text: '#F59E0B' };
            case 'Reject':
                return { bg: 'rgba(239, 68, 68, 0.2)', border: 'rgba(239, 68, 68, 0.4)', text: '#EF4444' };
            default:
                return { bg: 'rgba(148, 163, 184, 0.2)', border: 'rgba(148, 163, 184, 0.4)', text: '#94A3B8' };
        }
    };

    const getScoreColor = (score) => {
        if (score >= 80) return { bg: 'rgba(16, 185, 129, 0.2)', text: '#10B981' };
        if (score >= 60) return { bg: 'rgba(245, 158, 11, 0.2)', text: '#F59E0B' };
        return { bg: 'rgba(239, 68, 68, 0.2)', text: '#EF4444' };
    };

    /** Stage 2: المشاركة = رابط مقابلة الفيديو (LiveKit) وليس الصوت */
    const handleShare = async (candidate) => {
        const candidateId = candidate._id || candidate.id;
        const campaignId = candidate.campaignId;
        const q = new URLSearchParams({ candidateId: String(candidateId) });
        if (campaignId) q.set('campaignId', String(campaignId));
        const interviewLink = absoluteAppUrl(`/video-interview-call?${q.toString()}`);

        const candidateData = {
            name:
                ((candidate.full_name || candidate.fullName) || '').trim()
                || candidate.email?.split('@')[0]
                || t('stageEval_unknownCandidate'),
            position:
                candidate.position_applied_for || candidate.positionAppliedFor || na,
            score: candidate.voiceInterviewEvaluation?.overall_score || 0,
            recommendation: translateRecLabel(
                canonicalStageRecommendation(candidate.voiceInterviewEvaluation?.recommendation)
            ),
            summary: candidate.voiceInterviewEvaluation?.summary || t('stageEval_noSummary'),
            email: candidate.email || na,
            phone: candidate.phone || na,
        };

        const shareText = fillI18nTemplate(t('voiceInterview_shareBody'), {
            name: candidateData.name,
            position: candidateData.position,
            link: interviewLink,
            score: candidateData.score,
            recommendation: candidateData.recommendation,
            email: candidateData.email,
            phone: candidateData.phone,
            summary: candidateData.summary,
        });

        if (navigator.share) {
            try {
                await navigator.share({
                    title: fillI18nTemplate(t('voiceInterview_shareNavigatorTitle'), { name: candidateData.name }),
                    text: fillI18nTemplate(t('voiceInterview_shareNavigatorText'), {
                        name: candidateData.name,
                        position: candidateData.position,
                        link: interviewLink,
                    }),
                    url: interviewLink,
                });
                return;
            } catch (err) {
                if (err.name !== 'AbortError') {
                    console.error('Error sharing:', err);
                }
            }
        }

        try {
            await navigator.clipboard.writeText(shareText);
            alert(t('voiceInterview_shareCopyOk'));
        } catch (err) {
            console.error('Failed to copy:', err);
            prompt(`${t('voiceInterview_shareCopyPrompt')} `, shareText);
        }
    };

    const filteredCandidates = candidates.filter((c) =>
        recommendationMatchesFilter(c.voiceInterviewEvaluation?.recommendation, filter)
    );

    return (
        <>
            <style>{`
                @keyframes slideDown {
                    from {
                        opacity: 0;
                        max-height: 0;
                        transform: translateY(-10px);
                    }
                    to {
                        opacity: 1;
                        max-height: 1000px;
                        transform: translateY(0);
                    }
                }
            `}</style>
        <div style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #0F172A 0%, #1E293B 100%)' }}>
            <div
                className="design-container"
                style={{
                    paddingTop: '64px',
                    paddingBottom: '40px',
                    maxWidth: '1400px',
                    margin: '0 auto',
                    background: 'transparent',
                }}
            >
                <div className="design-header" style={{ marginBottom: '40px' }}>
                    <div className="header-content">
                        <h1 className="design-title" style={{ marginBottom: 0 }}>
                            {t('voiceInterviewPageTitle')}
                        </h1>
                        <p style={{ marginTop: '10px', color: '#94a3b8', fontSize: '15px' }}>{t('voiceInterviewSubtitle')}</p>
                    </div>
                    <div className="header-actions" style={{ flexWrap: 'wrap', gap: '10px' }}>
                        <button type="button" className="btn btn-secondary" onClick={fetchCandidates}>
                            <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                <path d="M16 10C16 13.3137 13.3137 16 10 16C6.68629 16 4 13.3137 4 10C4 6.68629 6.68629 4 10 4C11.82 4 13.45 4.81 14.55 6.08" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                                <path d="M16 4V8H12" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                            </svg>
                            <span className="btn-text">{t('stageEval_refresh')}</span>
                        </button>
                        {['all', 'Hire', 'Consider', 'Reject'].map((filterOption) => {
                            const isActive = filter === filterOption.toLowerCase();
                            return (
                                <button
                                    key={filterOption}
                                    type="button"
                                    className="btn btn-secondary"
                                    onClick={() => setFilter(filterOption.toLowerCase())}
                                    style={{
                                        background: isActive ? 'rgba(34, 211, 238, 0.2)' : 'rgba(15, 23, 42, 0.8)',
                                        borderColor: isActive ? 'rgba(34, 211, 238, 0.6)' : 'rgba(34, 211, 238, 0.3)',
                                        color: isActive ? '#22d3ee' : 'rgba(255, 255, 255, 0.95)',
                                    }}
                                >
                                    {filterOption === 'all' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <path d="M2.5 5H17.5M5 10H15M7.5 15H12.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                        </svg>
                                    )}
                                    {filterOption === 'Hire' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <path d="M10 2.5L12.5 7.5L17.5 8.75L14.5 12.5L15.5 17.5L10 15L4.5 17.5L5.5 12.5L2.5 8.75L7.5 7.5L10 2.5Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                        </svg>
                                    )}
                                    {filterOption === 'Consider' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <circle cx="10" cy="10" r="7.5" stroke="currentColor" strokeWidth="2"/>
                                            <path d="M10 6V10L13 13" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                        </svg>
                                    )}
                                    {filterOption === 'Reject' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <circle cx="10" cy="10" r="7.5" stroke="currentColor" strokeWidth="2"/>
                                            <path d="M7.5 7.5L12.5 12.5M12.5 7.5L7.5 12.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                        </svg>
                                    )}
                                    <span className="btn-text">
                                        {filterOption === 'all'
                                            ? t('stageEval_all')
                                            : filterOption === 'Hire'
                                              ? t('stageEval_recHire')
                                              : filterOption === 'Consider'
                                                ? t('stageEval_recConsider')
                                                : t('stageEval_recReject')}
                                    </span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* Table */}
                {loading ? (
                    <div style={{ textAlign: 'center', padding: '60px', color: '#94A3B8' }}>
                        {t('stageEval_loading')}
                    </div>
                ) : (
                    <div style={{
                        background: 'rgba(15, 23, 42, 0.5)',
                        borderRadius: '12px',
                        border: '1px solid rgba(34, 211, 238, 0.2)',
                        overflow: 'hidden',
                        boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)'
                    }}>
                        <div style={{ overflowX: 'auto', scrollbarWidth: 'none', msOverflowStyle: 'none' }}>
                            <style>{`
                                div::-webkit-scrollbar {
                                    display: none;
                                }
                            `}</style>
                            <table style={{ 
                                width: '100%', 
                                borderCollapse: 'separate',
                                borderSpacing: 0,
                                border: '1px solid rgba(34, 211, 238, 0.2)',
                                borderRadius: '8px',
                                overflow: 'hidden'
                            }}>
                                <thead>
                                    <tr style={{ 
                                        background: 'linear-gradient(180deg, rgba(30, 41, 59, 0.95) 0%, rgba(15, 23, 42, 0.95) 100%)',
                                        borderBottom: '2px solid rgba(34, 211, 238, 0.5)'
                                    }}>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'left', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px', 
                                            width: '40px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}></th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'left', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            minWidth: '250px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colCandidate')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colCommunicationSkills')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colEnglishFluency')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colConfidenceLevel')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colProblemSolving')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colComputerSkills')}</th>
                                        <th style={{ 
                                            padding: '16px 8px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '13px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                            whiteSpace: 'nowrap',
                                            width: '1%',
                                            maxWidth: '118px',
                                            minWidth: '100px'
                                        }}>{t('stageEval_colRecommendation')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px', 
                                            width: '80px'
                                        }}>{t('stageEval_colShare')}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredCandidates.map((candidate, index) => {
                                        const evaluation = candidate.voiceInterviewEvaluation;
                                        const strengthItems = normalizeVoiceBulletList(evaluation?.strengths);
                                        const weaknessItems = normalizeVoiceBulletList(evaluation?.weaknesses);
                                        const scoreColors = getScoreColor(evaluation?.overall_score || 0);
                                        const recCanon = canonicalStageRecommendation(evaluation?.recommendation);
                                        const recColors = getRecommendationColor(recCanon);
                                        const candidateId = candidate._id || candidate.id;
                                        const isExpanded = expandedRows.has(candidateId);
                                        const photoUrl = candidatePhotoUrl(candidate);
                                        
                                        const toggleRow = (e) => {
                                            // Don't expand if clicking on share button
                                            if (e.target.tagName === 'BUTTON' || e.target.closest('button')) {
                                                return;
                                            }
                                            setExpandedRows(prev => {
                                                const newSet = new Set(prev);
                                                if (newSet.has(candidateId)) {
                                                    newSet.delete(candidateId);
                                                } else {
                                                    newSet.add(candidateId);
                                                }
                                                return newSet;
                                            });
                                        };
                                        
                                        return (
                                            <React.Fragment key={candidateId}>
                                            <tr 
                                                style={{
                                                    borderTop: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderBottom: index < filteredCandidates.length - 1 ? '1px solid rgba(34, 211, 238, 0.3)' : '1px solid rgba(34, 211, 238, 0.3)',
                                                    transition: 'all 0.2s ease',
                                                    cursor: 'pointer',
                                                    background: 'transparent'
                                                }}
                                                onClick={toggleRow}
                                                onMouseEnter={(e) => {
                                                    e.currentTarget.style.background = 'rgba(34, 211, 238, 0.05)';
                                                    e.currentTarget.style.borderTop = '1px solid rgba(34, 211, 238, 0.5)';
                                                    e.currentTarget.style.borderBottom = '1px solid rgba(34, 211, 238, 0.5)';
                                                }}
                                                onMouseLeave={(e) => {
                                                    e.currentTarget.style.background = 'transparent';
                                                    e.currentTarget.style.borderTop = '1px solid rgba(34, 211, 238, 0.3)';
                                                    e.currentTarget.style.borderBottom = index < filteredCandidates.length - 1 ? '1px solid rgba(34, 211, 238, 0.3)' : '1px solid rgba(34, 211, 238, 0.3)';
                                                }}
                                            >
                                                {/* Expand/Collapse Icon */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center', 
                                                    width: '40px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <svg 
                                                        width="20" 
                                                        height="20" 
                                                        viewBox="0 0 20 20" 
                                                        fill="none" 
                                                        xmlns="http://www.w3.org/2000/svg"
                                                        style={{
                                                            transform: isExpanded ? 'rotate(90deg)' : 'rotate(0deg)',
                                                            transition: 'transform 0.3s ease',
                                                            color: '#22d3ee'
                                                        }}
                                                    >
                                                        <path d="M7.5 5L12.5 10L7.5 15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                    </svg>
                                                </td>
                                                {/* Candidate Name */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    minWidth: '250px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{ display: 'flex', alignItems: 'flex-start', gap: '12px' }}>
                                                        {/* Profile Photo */}
                                                        <div
                                                            className="candidate-avatar-ring"
                                                            style={{
                                                            width: '52px',
                                                            height: '52px',
                                                            borderRadius: '50%',
                                                            overflow: 'hidden',
                                                            flexShrink: 0,
                                                            border: '2px solid rgba(34, 211, 238, 0.35)',
                                                            background: 'linear-gradient(135deg, #06B6D4, #3B82F6)',
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            boxShadow: '0 2px 8px rgba(6, 182, 212, 0.2)'
                                                        }}
                                                        >
                                                            {photoUrl ? (
                                                                <img 
                                                                    alt={((candidate.full_name || candidate.fullName) || '').trim() || t('stageEval_profilePhotoAlt')} 
                                                                    className="candidate-avatar-photo"
                                                                    decoding="async"
                                                                    draggable={false}
                                                                    {...candidateAvatarImageProps(photoUrl, 52)}
                                                                    style={{ 
                                                                        width: '100%', 
                                                                        height: '100%', 
                                                                        objectFit: 'cover' 
                                                                    }}
                                                                    onError={(e) => {
                                                                        e.target.style.display = 'none';
                                                                        const fall = e.target.nextElementSibling;
                                                                        if (fall) fall.style.display = 'flex';
                                                                    }}
                                                                />
                                                            ) : null}
                                                            {shouldUseGenderAvatar(candidate, photoUrl) ? (
                                                                <GenderAvatar
                                                                    gender={inferGenderFromName(candidate)}
                                                                    size={52}
                                                                />
                                                            ) : (
                                                                <div style={{
                                                                    display: photoUrl ? 'none' : 'flex',
                                                                    alignItems: 'center',
                                                                    justifyContent: 'center',
                                                                    width: '100%',
                                                                    height: '100%',
                                                                    fontSize: '20px',
                                                                    fontWeight: 600,
                                                                    color: '#fff'
                                                                }}>
                                                                    {((candidate.full_name || candidate.fullName)?.[0] || candidate.email?.[0] || '?').toUpperCase()}
                                                                </div>
                                                            )}
                                                        </div>
                                                        <div style={{ flex: 1, minWidth: 0 }}>
                                                            <div style={{ 
                                                                color: '#F1F5F9', 
                                                                fontWeight: 600, 
                                                                marginBottom: '4px',
                                                                whiteSpace: 'normal',
                                                                wordWrap: 'break-word',
                                                                lineHeight: '1.4',
                                                                fontSize: '14px'
                                                            }}>
                                                                {((candidate.full_name || candidate.fullName) || '').trim()
                                                                    ? (candidate.full_name || candidate.fullName).trim()
                                                                    : candidate.email?.split('@')[0] || t('stageEval_unknownCandidate')
                                                                }
                                                            </div>
                                                        <div style={{ 
                                                            color: '#94A3B8', 
                                                            fontSize: '12px',
                                                            whiteSpace: 'normal',
                                                            wordWrap: 'break-word',
                                                            lineHeight: '1.4',
                                                            marginBottom: '4px'
                                                        }}>
                                                            {candidate.position_applied_for || candidate.positionAppliedFor || na}
                                                        </div>
                                                        {candidate.createdAt && (
                                                            <div style={{ 
                                                                color: '#64748B', 
                                                                fontSize: '11px',
                                                                whiteSpace: 'normal',
                                                                wordWrap: 'break-word',
                                                                lineHeight: '1.3',
                                                                marginTop: '4px',
                                                                display: 'flex',
                                                                alignItems: 'center',
                                                                gap: '4px'
                                                            }}>
                                                                <svg width="12" height="12" viewBox="0 0 12 12" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity: 0.7 }}>
                                                                    <circle cx="6" cy="6" r="5" stroke="currentColor" strokeWidth="1"/>
                                                                    <path d="M6 3V6L8 8" stroke="currentColor" strokeWidth="1" strokeLinecap="round"/>
                                                                </svg>
                                                                {new Date(candidate.createdAt).toLocaleString('en-US', {
                                                                    year: 'numeric',
                                                                    month: 'short',
                                                                    day: 'numeric',
                                                                    hour: '2-digit',
                                                                    minute: '2-digit'
                                                                })}
                                                            </div>
                                                        )}
                                                        </div>
                                                    </div>
                                                </td>

                                                {/* Communication */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{
                                                        color: '#CBD5E1',
                                                        fontSize: '14px',
                                                        fontWeight: 500
                                                    }}>
                                                        {formatVoiceSkill(evaluation?.communication, na, skillOutTen)}
                                                    </div>
                                                </td>

                                                {/* Language Fluency */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{
                                                        color: '#CBD5E1',
                                                        fontSize: '14px',
                                                        fontWeight: 500
                                                    }}>
                                                        {displayVoiceText(evaluation?.language_fluency, na)}
                                                    </div>
                                                </td>

                                                {/* Confidence */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{
                                                        color: '#CBD5E1',
                                                        fontSize: '14px',
                                                        fontWeight: 500
                                                    }}>
                                                        {displayVoiceText(evaluation?.confidence, na)}
                                                    </div>
                                                </td>

                                                {/* Problem Solving */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{
                                                        color: '#CBD5E1',
                                                        fontSize: '14px',
                                                        fontWeight: 500
                                                    }}>
                                                        {formatVoiceSkill(evaluation?.problem_solving, na, skillOutTen)}
                                                    </div>
                                                </td>

                                                {/* Digital Skills */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{
                                                        color: '#CBD5E1',
                                                        fontSize: '14px',
                                                        fontWeight: 500
                                                    }}>
                                                        {displayVoiceText(evaluation?.digital_skills, na)}
                                                    </div>
                                                </td>

                                                {/* Score + Recommendation (مثل Stage 1) */}
                                                <td style={{ 
                                                    padding: '10px 6px', 
                                                    textAlign: 'center',
                                                    verticalAlign: 'middle',
                                                    maxWidth: '118px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{
                                                        display: 'flex',
                                                        flexDirection: 'column',
                                                        alignItems: 'center',
                                                        justifyContent: 'center',
                                                        gap: '6px',
                                                        width: '100%'
                                                    }}>
                                                        <div style={{
                                                            display: 'inline-block',
                                                            padding: '5px 10px',
                                                            borderRadius: '6px',
                                                            background: scoreColors.bg,
                                                            color: scoreColors.text,
                                                            fontWeight: 700,
                                                            fontSize: '14px',
                                                            lineHeight: 1.15
                                                        }}>
                                                            {evaluation?.overall_score || 0}%
                                                        </div>
                                                        <div style={{
                                                            display: 'inline-block',
                                                            padding: '4px 8px',
                                                            borderRadius: '5px',
                                                            background: recColors.bg,
                                                            border: `1px solid ${recColors.border}`,
                                                            color: recColors.text,
                                                            fontWeight: 600,
                                                            fontSize: '11px',
                                                            lineHeight: 1.15,
                                                            letterSpacing: '0.02em',
                                                        }}>
                                                            {translateRecLabel(recCanon)}
                                                        </div>
                                                    </div>
                                                </td>

                                                {/* Share Button */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <button
                                                        onClick={() => handleShare(candidate)}
                                                        title={t('voiceInterviewShareTitle')}
                                                        style={{
                                                            width: '48px',
                                                            height: '48px',
                                                            borderRadius: '50%',
                                                            border: 'none',
                                                            background: 'linear-gradient(135deg, #10B981 0%, #059669 100%)',
                                                            backdropFilter: 'blur(10px)',
                                                            color: '#fff',
                                                            cursor: 'pointer',
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            fontSize: '20px',
                                                            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                                                            boxShadow: '0 4px 12px rgba(16, 185, 129, 0.3), 0 0 0 1px rgba(34, 211, 238, 0.4)',
                                                            position: 'relative',
                                                            overflow: 'hidden'
                                                        }}
                                                        onMouseEnter={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1.1) rotate(360deg)';
                                                            e.currentTarget.style.background = 'linear-gradient(135deg, #059669 0%, #047857 100%)';
                                                            e.currentTarget.style.boxShadow = '0 8px 24px rgba(16, 185, 129, 0.5), 0 0 0 2px rgba(34, 211, 238, 0.6)';
                                                        }}
                                                        onMouseLeave={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1) rotate(0deg)';
                                                            e.currentTarget.style.background = 'linear-gradient(135deg, #10B981 0%, #059669 100%)';
                                                            e.currentTarget.style.boxShadow = '0 4px 12px rgba(16, 185, 129, 0.3), 0 0 0 1px rgba(34, 211, 238, 0.4)';
                                                        }}
                                                        onMouseDown={(e) => {
                                                            e.currentTarget.style.transform = 'scale(0.95)';
                                                        }}
                                                        onMouseUp={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1.1) rotate(360deg)';
                                                        }}
                                                    >
                                                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                                            <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                            <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                        </svg>
                                                    </button>
                                                </td>
                                            </tr>
                                            
                                            {/* Expanded Details Row */}
                                            {isExpanded && (
                                                <tr style={{
                                                    background: 'rgba(15, 23, 42, 0.6)',
                                                    borderBottom: index < filteredCandidates.length - 1 ? '1px solid rgba(34, 211, 238, 0.2)' : 'none',
                                                    borderTop: '1px solid rgba(34, 211, 238, 0.2)'
                                                }}>
                                                    <td colSpan={9} style={{ padding: '0' }}>
                                                        <div style={{
                                                            padding: '24px',
                                                            animation: 'slideDown 0.3s ease-out'
                                                        }}>
                                                            <div style={{
                                                                display: 'grid',
                                                                gridTemplateColumns: 'repeat(2, 1fr)',
                                                                gap: '20px',
                                                                marginBottom: '20px'
                                                            }}>
                                                                {/* Summary */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        {t('stageEval_summary')}
                                                                    </h4>
                                                                    <p style={{ color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8', margin: 0 }}>
                                                                        {displayVoiceText(evaluation?.summary, t('stageEval_noSummary'))}
                                                                    </p>
                                                                </div>

                                                                {/* Weaknesses */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        {t('stageEval_weaknesses')}
                                                                    </h4>
                                                                    {weaknessItems.length > 0 ? (
                                                                        <ul style={{ margin: 0, paddingLeft: '20px', color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8' }}>
                                                                            {weaknessItems.map((w, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{displayVoiceText(w, '')}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : evaluation?.red_flags && evaluation.red_flags.length > 0 ? (
                                                                        <ul style={{ margin: 0, paddingLeft: '20px', color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8' }}>
                                                                            {evaluation.red_flags.map((flag, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{flag}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : (
                                                                        <span style={{ color: '#94A3B8', fontSize: '13px' }}>{t('stageEval_none')}</span>
                                                                    )}
                                                                </div>

                                                                {/* Strengths */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        {t('stageEval_strengths')}
                                                                    </h4>
                                                                    {strengthItems.length > 0 ? (
                                                                        <ul style={{ margin: 0, paddingLeft: '20px', color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8' }}>
                                                                            {strengthItems.map((strength, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{displayVoiceText(strength, '')}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : (
                                                                        <span style={{ color: '#94A3B8', fontSize: '13px' }}>{t('stageEval_none')}</span>
                                                                    )}
                                                                </div>

                                                                {/* Professional Attitude */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        {t('stageEval_professionalAttitude')}
                                                                    </h4>
                                                                    <p style={{ color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8', margin: 0 }}>
                                                                        {displayVoiceText(
                                                                            evaluation?.professional_attitude ?? evaluation?.fit_for_role,
                                                                            t('stageEval_none')
                                                                        )}
                                                                    </p>
                                                                </div>

                                                                {/* Final HR Evaluation */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        {t('stageEval_finalHrEval')}
                                                                    </h4>
                                                                    <p style={{ color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8', margin: 0 }}>
                                                                        {displayVoiceText(
                                                                            evaluation?.final_hr_evaluation ??
                                                                                evaluation?.finalHrEvaluation ??
                                                                                evaluation?.recommendation,
                                                                            t('voiceInterview_noFinalHr')
                                                                        )}
                                                                    </p>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </td>
                                                </tr>
                                            )}
                                            </React.Fragment>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* Stats — interview-eval-stat-card في index.css (زجاج سماوي عند hover) */}
                {!loading && candidates.length > 0 && (
                    <div
                        className="interview-eval-stats-grid"
                        style={{
                            marginTop: '30px',
                            display: 'grid',
                            gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
                            gap: '20px',
                        }}
                    >
                        <div className="interview-eval-stat-card">
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_totalEvaluations')}</div>
                            <div style={{ color: '#F1F5F9', fontSize: '28px', fontWeight: 700 }}>{candidates.length}</div>
                        </div>
                        <div className="interview-eval-stat-card">
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_recHire')}</div>
                            <div style={{ color: '#10B981', fontSize: '28px', fontWeight: 700 }}>
                                {candidates.filter(c => c.voiceInterviewEvaluation?.recommendation === 'Hire').length}
                            </div>
                        </div>
                        <div className="interview-eval-stat-card">
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_recConsider')}</div>
                            <div style={{ color: '#F59E0B', fontSize: '28px', fontWeight: 700 }}>
                                {candidates.filter(c => c.voiceInterviewEvaluation?.recommendation === 'Consider').length}
                            </div>
                        </div>
                        <div className="interview-eval-stat-card">
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_recReject')}</div>
                            <div style={{ color: '#EF4444', fontSize: '28px', fontWeight: 700 }}>
                                {candidates.filter(c => c.voiceInterviewEvaluation?.recommendation === 'Reject').length}
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
        </>
    );
};

export default VoiceInterview;





