import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { POSITION_SUGGESTIONS } from '../constants/positionSuggestions.js';
import { useLanguage } from '../contexts/LanguageContext';
import positionLabelsAr from '../constants/positionLabels.ar.json';
import positionLabelsKu from '../constants/positionLabels.ku.json';
import locationLabelsAr from '../constants/locationLabels.ar.json';
import locationLabelsKu from '../constants/locationLabels.ku.json';

/**
 * Position / job-title field with a dropdown styled like the nav language menu
 * (`.language-dropdown-menu` + `.language-option`), replacing native `<datalist>`.
 *
 * Optional `suggestionOptions` `{ value, label }[]` keeps stored `value` codes while
 * showing labels in the list; users can still type free text (stored as typed unless
 * it exactly matches a label or value, then the canonical `value` is stored).
 *
 * When only `suggestions` (string[]) is passed, labels are localized for ar/ku using
 * `positionLabels.{ar,ku}.json` and `locationLabels.{ar,ku}.json` when the English string exists;
 * stored value stays English (canonical suggestion key).
 */
export default function PositionSuggestCombobox({
    id,
    name,
    value,
    onChange,
    onFocus: onFocusProp,
    onBlur: onBlurProp,
    onKeyDown: onKeyDownProp,
    placeholder,
    className = '',
    required,
    disabled,
    autoComplete = 'off',
    suggestions = POSITION_SUGGESTIONS,
    suggestionOptions: suggestionOptionsProp,
    inputStyle,
    chevronStyle,
    listboxId: listboxIdProp,
    wrapperClassName = '',
}) {
    const { currentLang } = useLanguage();
    const wrapperRef = useRef(null);
    const blurCloseTimer = useRef(null);
    const [menuOpen, setMenuOpen] = useState(false);
    const listboxId = listboxIdProp || (id ? `${id}-suggestions` : undefined);

    const effectiveSuggestionOptions = useMemo(() => {
        if (suggestionOptionsProp?.length) return suggestionOptionsProp;
        let catalog = null;
        if (currentLang === 'ar') {
            catalog = { ...positionLabelsAr, ...locationLabelsAr };
        } else if (currentLang === 'ku') {
            catalog = { ...positionLabelsKu, ...locationLabelsKu };
        }
        return suggestions.map((en) => ({
            value: en,
            label: catalog?.[en] ?? en,
        }));
    }, [suggestionOptionsProp, suggestions, currentLang]);

    const useOptionsMode = effectiveSuggestionOptions.length > 0;

    const labelByValue = useMemo(() => {
        if (!useOptionsMode) return null;
        return Object.fromEntries(effectiveSuggestionOptions.map((o) => [o.value, o.label]));
    }, [useOptionsMode, effectiveSuggestionOptions]);

    const displayFromStored = useCallback(
        (v) => {
            if (v == null || v === '') return '';
            if (labelByValue && Object.prototype.hasOwnProperty.call(labelByValue, v)) {
                return labelByValue[v];
            }
            return String(v);
        },
        [labelByValue]
    );

    const [text, setText] = useState(() => displayFromStored(value));

    useEffect(() => {
        setText(displayFromStored(value));
    }, [value, displayFromStored]);

    const resolveStoredFromText = useCallback(
        (typed) => {
            if (!useOptionsMode) return typed;
            const trimmed = typed.trim();
            if (!trimmed) return '';
            const byLabel = effectiveSuggestionOptions.find(
                (o) => o.label.toLowerCase() === trimmed.toLowerCase()
            );
            if (byLabel) return byLabel.value;
            const byVal = effectiveSuggestionOptions.find(
                (o) => o.value.toLowerCase() === trimmed.toLowerCase()
            );
            if (byVal) return byVal.value;
            return typed;
        },
        [useOptionsMode, effectiveSuggestionOptions]
    );

    const filtered = useMemo(() => {
        if (!useOptionsMode) {
            const q = String(value ?? '').trim().toLowerCase();
            if (!q) return suggestions;
            return suggestions.filter((x) => String(x).toLowerCase().includes(q));
        }
        const q = String(text ?? '').trim().toLowerCase();
        if (!q) return effectiveSuggestionOptions;
        return effectiveSuggestionOptions.filter(
            (o) =>
                o.label.toLowerCase().includes(q) || o.value.toLowerCase().includes(q)
        );
    }, [useOptionsMode, text, value, suggestions, effectiveSuggestionOptions]);

    const showMenu = menuOpen && filtered.length > 0 && !disabled;

    const clearCloseTimer = () => {
        if (blurCloseTimer.current) {
            clearTimeout(blurCloseTimer.current);
            blurCloseTimer.current = null;
        }
    };

    const emitChange = useCallback(
        (nextValue) => {
            if (!onChange) return;
            onChange({ target: { name: name ?? '', value: nextValue } });
        },
        [name, onChange]
    );

    const pickSuggestion = (item) => {
        clearCloseTimer();
        if (useOptionsMode && item && typeof item === 'object' && 'value' in item) {
            setText(item.label);
            emitChange(item.value);
        } else {
            emitChange(item);
        }
        setMenuOpen(false);
    };

    useEffect(() => {
        if (!showMenu) return;
        const onDocDown = (e) => {
            if (wrapperRef.current && !wrapperRef.current.contains(e.target)) {
                setMenuOpen(false);
            }
        };
        document.addEventListener('mousedown', onDocDown);
        return () => document.removeEventListener('mousedown', onDocDown);
    }, [showMenu]);

    useEffect(() => () => clearCloseTimer(), []);

    return (
        <div
            className={['position-suggest-combobox-wrapper', wrapperClassName].filter(Boolean).join(' ')}
            ref={wrapperRef}
        >
            <input
                type="text"
                id={id}
                name={name}
                value={useOptionsMode ? text : (value ?? '')}
                onChange={(e) => {
                    const raw = e.target.value;
                    if (useOptionsMode) {
                        setText(raw);
                        emitChange(resolveStoredFromText(raw));
                    } else {
                        onChange?.(e);
                    }
                    setMenuOpen(true);
                }}
                onKeyDown={(e) => {
                    onKeyDownProp?.(e);
                }}
                onFocus={(e) => {
                    clearCloseTimer();
                    setMenuOpen(true);
                    onFocusProp?.(e);
                }}
                onBlur={(e) => {
                    blurCloseTimer.current = setTimeout(() => setMenuOpen(false), 180);
                    onBlurProp?.(e);
                }}
                placeholder={placeholder}
                className={className}
                required={required}
                disabled={disabled}
                autoComplete={autoComplete}
                aria-expanded={showMenu}
                aria-controls={listboxId}
                aria-autocomplete="list"
                role="combobox"
                style={inputStyle ? { paddingRight: '2.75rem', ...inputStyle } : { paddingRight: '2.75rem' }}
            />
            <span
                aria-hidden
                className="position-suggest-chevron"
                style={{
                    position: 'absolute',
                    right: '14px',
                    top: '50%',
                    transform: 'translateY(-50%)',
                    pointerEvents: 'none',
                    color: 'var(--primary-color, #6366f1)',
                    opacity: 0.85,
                    display: 'flex',
                    alignItems: 'center',
                    ...(chevronStyle || {}),
                }}
            >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M6 9l6 6 6-6" stroke="currentColor" strokeWidth="2.75" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
            </span>
            <div
                id={listboxId}
                className={`language-dropdown-menu position-suggest-dropdown ${showMenu ? 'active' : ''}`}
                role="listbox"
                hidden={!showMenu}
            >
                {useOptionsMode
                    ? filtered.map((opt) => (
                          <button
                              key={opt.value}
                              type="button"
                              className={`language-option ${String(value ?? '') === opt.value ? 'active' : ''}`}
                              role="option"
                              aria-selected={String(value ?? '') === opt.value}
                              onMouseDown={(e) => e.preventDefault()}
                              onClick={() => pickSuggestion(opt)}
                          >
                              <span className="language-name">{opt.label}</span>
                          </button>
                      ))
                    : filtered.map((title) => (
                          <button
                              key={title}
                              type="button"
                              className={`language-option ${String(value ?? '') === title ? 'active' : ''}`}
                              role="option"
                              aria-selected={String(value ?? '') === title}
                              onMouseDown={(e) => e.preventDefault()}
                              onClick={() => pickSuggestion(title)}
                          >
                              <span className="language-name">{title}</span>
                          </button>
                      ))}
            </div>
        </div>
    );
}
