import React from 'react';
import LegalPageShell from '../components/LegalPageShell';
import { useLanguage } from '../contexts/LanguageContext';

/** Copy from translations — wire mailto / support URL from app config later. */
export default function ContactPage() {
    const { t } = useLanguage();

    return (
        <LegalPageShell title={t('contact')}>
            <p>{t('contactPageP1')}</p>
            <p>{t('contactPageP2')}</p>
            <p>{t('contactPageEmailLine')}</p>
        </LegalPageShell>
    );
}
