import React, { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import AccountSidebar from '../components/AccountSidebar';
import AccountPageLayout from '../components/AccountPageLayout';
import { useAuth } from '../contexts/AuthContext';
import { useLanguage } from '../contexts/LanguageContext';
import { getSessionStartedAtMs } from '../services/authService';
import {
    formatSessionRelativeTime,
    getBrowserDeviceLabel,
} from '../utils/accountSessions';
import {
    accountPageH1Style,
    accountSectionLabelStyle,
    ACCOUNT_TEXT_PRIMARY,
    ACCOUNT_TEXT_MUTED,
} from '../utils/accountTypography';

const BORDER = 'rgba(255, 255, 255, 0.1)';
const MUTED = ACCOUNT_TEXT_MUTED;

function IconMonitor(props) {
    return (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
            <rect x="2" y="3" width="20" height="14" rx="2" />
            <path d="M8 21h8M12 17v4" />
        </svg>
    );
}

function SectionLabel({ children }) {
    return <div style={accountSectionLabelStyle}>{children}</div>;
}

const AccountSettings = () => {
    const navigate = useNavigate();
    const { session, logout } = useAuth();
    const { currentLang, t } = useLanguage();
    const [fullName, setFullName] = useState('ali mahmood');
    const [company, setCompany] = useState('');
    const [email, setEmail] = useState('ali.mahmood@example.com');
    const [revokingSession, setRevokingSession] = useState(false);
    const [loggingOut, setLoggingOut] = useState(false);
    const [deletingAccount, setDeletingAccount] = useState(false);

    const relLocale = currentLang === 'ar' ? 'ar' : currentLang === 'ku' ? 'ku' : 'en';

    const activeSessionRow = useMemo(() => {
        if (!session?.token) return null;
        const startedAt = getSessionStartedAtMs(session);
        return {
            id: `${session.user?.id ?? 'session'}-${String(session.token).slice(0, 16)}`,
            device: getBrowserDeviceLabel(),
            created: formatSessionRelativeTime(startedAt, relLocale),
        };
    }, [session, relLocale]);

    const handleRevokeCurrentSession = async () => {
        if (!session?.token || revokingSession) return;
        setRevokingSession(true);
        try {
            await logout();
            navigate('/login');
        } finally {
            setRevokingSession(false);
        }
    };

    const handleLogOut = async () => {
        if (loggingOut || deletingAccount) return;
        setLoggingOut(true);
        try {
            await logout();
            navigate('/login');
        } finally {
            setLoggingOut(false);
        }
    };

    const handleDeleteAccount = async () => {
        const confirmMsg = t('account_settingsDeleteConfirm');
        if (!window.confirm(confirmMsg)) return;
        if (deletingAccount || loggingOut) return;
        setDeletingAccount(true);
        try {
            await logout();
            navigate('/login');
            window.alert(t('account_settingsDeleteDone'));
        } finally {
            setDeletingAccount(false);
        }
    };

    const settingsInjectStyle = `
                @media (max-width: 960px) {
                    .account-dashboard-inner { flex-direction: column !important; }
                    .account-settings-page aside {
                        position: relative !important;
                        top: 0 !important;
                        width: 100% !important;
                    }
                }
            `;

    return (
        <AccountPageLayout pageClass="account-settings-page" injectStyle={settingsInjectStyle}>
                <AccountSidebar activeId="settings" />

                <main
                    dir={currentLang === 'ar' || currentLang === 'ku' ? 'rtl' : 'ltr'}
                    style={{ flex: 1, minWidth: 0 }}
                >
                    <h1 style={accountPageH1Style('0 0 28px')}>{t('account_settingsTitle')}</h1>

                    {/* Profile */}
                    <SectionLabel>{t('account_profileSection')}</SectionLabel>
                    <div className="dashboard-card" style={{ padding: '20px 22px', marginBottom: 24 }}>
                        <div
                            style={{
                                display: 'flex',
                                flexDirection: 'column',
                                gap: 20,
                                marginBottom: 20,
                            }}
                            className="account-settings-profile-grid"
                        >
                            <div>
                                <label htmlFor="settings-full-name" className="account-settings-label">
                                    {t('account_settingsFullName')}
                                </label>
                                <input
                                    id="settings-full-name"
                                    className="account-settings-input"
                                    value={fullName}
                                    onChange={(e) => setFullName(e.target.value)}
                                    autoComplete="name"
                                />
                            </div>
                            <div>
                                <label htmlFor="settings-company" className="account-settings-label">
                                    {t('account_settingsCompany')}
                                </label>
                                <input
                                    id="settings-company"
                                    className="account-settings-input"
                                    value={company}
                                    onChange={(e) => setCompany(e.target.value)}
                                    autoComplete="organization"
                                />
                            </div>
                            <div>
                                <label htmlFor="settings-email" className="account-settings-label">
                                    {t('account_settingsEmail')}
                                </label>
                                <input
                                    id="settings-email"
                                    className="account-settings-input"
                                    type="email"
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    autoComplete="email"
                                    inputMode="email"
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                            <button type="button" className="workflow-btn-primary account-btn-compact">
                                {t('account_settingsSave')}
                            </button>
                        </div>
                    </div>

                    {/* Active Sessions */}
                    <SectionLabel>{t('account_sessionsSection')}</SectionLabel>
                    <div
                        className="dashboard-card"
                        style={{
                            padding: 0,
                            marginBottom: 12,
                            overflowX: 'auto',
                        }}
                    >
                        <div
                            style={{
                                display: 'grid',
                                gridTemplateColumns: 'minmax(140px, 1fr) minmax(140px, 1fr) auto',
                                gap: 12,
                                padding: '16px 22px 12px',
                                borderBottom: `1px solid ${BORDER}`,
                                fontSize: 12,
                                color: MUTED,
                                fontWeight: 500,
                            }}
                            className="account-sessions-header"
                        >
                            <span>{t('account_settingsDevice')}</span>
                            <span>{t('account_settingsCreated')}</span>
                            <span style={{ width: 88 }} aria-hidden="true" />
                        </div>
                        <div style={{ minWidth: 0 }}>
                            {!activeSessionRow ? (
                                <div style={{ padding: '22px', fontSize: 14, color: MUTED, textAlign: 'center' }}>
                                    {t('account_settingsNoSessions')}
                                </div>
                            ) : (
                                <div
                                    style={{
                                        display: 'grid',
                                        gridTemplateColumns: 'minmax(140px, 1fr) minmax(140px, 1fr) auto',
                                        gap: 12,
                                        alignItems: 'center',
                                        padding: '14px 22px',
                                        borderBottom: 'none',
                                    }}
                                    className="account-sessions-row"
                                >
                                    <div
                                        style={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 10,
                                            fontSize: 14,
                                            color: '#fff',
                                            minWidth: 0,
                                            flexWrap: 'wrap',
                                        }}
                                    >
                                        <IconMonitor style={{ flexShrink: 0, opacity: 0.85 }} />
                                        <span>{activeSessionRow.device}</span>
                                        <span
                                            style={{
                                                fontSize: 11,
                                                fontWeight: 600,
                                                padding: '2px 8px',
                                                borderRadius: 4,
                                                background: 'rgba(34, 197, 94, 0.15)',
                                                color: '#86efac',
                                            }}
                                        >
                                            {t('account_settingsCurrentSession')}
                                        </span>
                                    </div>
                                    <div style={{ fontSize: 14, color: MUTED }}>{activeSessionRow.created}</div>
                                    <button
                                        type="button"
                                        className="workflow-btn-primary account-btn-compact"
                                        disabled={revokingSession || loggingOut || deletingAccount}
                                        onClick={() => handleRevokeCurrentSession()}
                                    >
                                        {revokingSession ? t('account_settingsRevoking') : t('account_settingsRevoke')}
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                    <p style={{ margin: '0 0 28px', fontSize: 12, color: MUTED, lineHeight: 1.5 }}>
                        {t('account_settingsSessionsHint')}
                    </p>

                    {/* More */}
                    <SectionLabel>{t('account_settingsMoreSection')}</SectionLabel>
                    <div className="dashboard-card" style={{ padding: 0 }}>
                        <div
                            style={{
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'space-between',
                                gap: 16,
                                padding: '18px 22px',
                                borderBottom: `1px solid ${BORDER}`,
                                flexWrap: 'wrap',
                            }}
                        >
                            <span style={{ fontSize: 14, color: ACCOUNT_TEXT_PRIMARY, fontWeight: 500 }}>
                                {t('account_settingsLogOut')}
                            </span>
                            <button
                                type="button"
                                className="workflow-btn-primary account-btn-compact"
                                disabled={loggingOut || deletingAccount}
                                onClick={() => handleLogOut()}
                            >
                                {loggingOut ? t('account_settingsLoggingOut') : t('account_settingsLogOut')}
                            </button>
                        </div>
                        <div
                            style={{
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'space-between',
                                gap: 16,
                                padding: '18px 22px',
                                flexWrap: 'wrap',
                            }}
                        >
                            <span style={{ fontSize: 14, color: ACCOUNT_TEXT_PRIMARY, fontWeight: 500 }}>
                                {t('account_settingsDeleteAccount')}
                            </span>
                            <button
                                type="button"
                                className="workflow-btn-primary account-btn-compact account-btn-danger"
                                disabled={loggingOut || deletingAccount}
                                onClick={() => handleDeleteAccount()}
                            >
                                {deletingAccount ? t('account_settingsProcessing') : t('account_settingsDelete')}
                            </button>
                        </div>
                    </div>
                </main>
        </AccountPageLayout>
    );
};

export default AccountSettings;
